export const MILKIO_SKILL_FILES: Record<string, string> = {
    "docs/bootstrap.md": "# Bootstrap\n\n## 概述\n\nBootstrap 是 Milkio 的启动引导机制，用于在服务启动时初始化中间件、数据库连接、缓存等基础设施。Bootstrap 分为两种：**全局 Bootstrap** 和 **模块级 Bootstrap**。\n\n## 全局 Bootstrap\n\n全局 Bootstrap 在项目入口文件 `index.ts` 中注册，在服务启动时按顺序执行。\n\n### 注册方式\n\n```ts\n// /index.ts\nimport { createWorld, type MilkioInit } from 'milkio';\nimport { generated } from './.milkio/index.ts';\nimport { configSchema } from './.milkio/config-schema.ts';\nimport { loadDrizzle } from './app/bootstrap/drizzle/index.ts';\nimport { loadRedis } from './app/bootstrap/redis/index.ts';\nimport { loadUserAuth } from './app/modules/user/$bootstraps/user-auth.ts';\n\nexport async function create(options: MilkioInit) {\n  const world = await createWorld(generated, configSchema, {\n    ...options,\n    bootstraps: [loadRedis, loadDrizzle, loadUserAuth],\n  });\n\n  return world;\n}\n```\n\n**注意**：Bootstrap 的注册顺序很重要——Redis 应在 Drizzle 之前加载，认证应在数据库之后加载。\n\n### 失败告警（onError）\n\n`createWorld` 的 options 支持 `onError(report)`，**只对 fault（未意料/内部错误）调用**；fail（业务拒绝）只记 warn 日志、不会触发告警。`report` 包含真实 fault-code、data、stack、cause、executeId、path，适合直接接 Sentry/OTel：\n\n```ts\nconst world = await createWorld(generated, configSchema, {\n  ...options,\n  onError: (report) => {\n    Sentry.captureException(report.cause ?? new Error(report.code), {\n      tags: { code: report.code, executeId: report.executeId },\n    });\n  },\n  bootstraps: [loadRedis, loadDrizzle, loadUserAuth],\n});\n```\n\n客户端只会收到通用 `{ kind: \"fault\", code: \"INTERNAL_SERVER_ERROR\" }` + executeId，真实 fault-code/data/stack 只在这里和服务端日志中出现。\n\n### 典型全局 Bootstrap 示例\n\n#### 数据库连接（Drizzle）\n\n推荐使用 `@milkio/drizzle` 工具集来支持「测试随机数据库」：测试模式下 astra 会在请求头携带随机库名，服务端据此路由到对应库；无请求头时走默认库（本地调试/生产不受影响）。\n\n```ts\n// /app/bootstrap/drizzle/index.ts\nimport { drizzle } from 'drizzle-orm/mysql2';\nimport mysql from 'mysql2/promise';\nimport { getTestDatabaseId, withTestDatabase } from '@milkio/drizzle';\nimport * as schema from '../../../.milkio/drizzle-schema.ts';\n\nconst pools = new Map<string, mysql.Pool | mysql.Connection>();\n\nexport function loadDrizzle(world: MilkioWorld<typeof generated>) {\n  world.on('milkio:executeBefore', async (event) => {\n    const databaseId = getTestDatabaseId(event.context.headers);\n    const url = withTestDatabase(world.config.drizzle.url, databaseId);\n\n    let pool = pools.get(url);\n    if (!pool) {\n      pool = world.isTestMode\n        ? await mysql.createConnection({ uri: url, timezone: '+00:00' })\n        : mysql.createPool({ uri: url, connectionLimit: 8 });\n      pools.set(url, pool);\n    }\n\n    // 只挂 context.db；事务用 context.db.transaction(async (tx) => ...) 显式管理\n    event.context.db = drizzle(pool, { schema, mode: 'default' });\n  });\n}\n```\n\n**`world.isTestMode`**：`MilkioWorld` 内置的布尔值（等价于 `world.config.mode === 'test'`），用于区分测试与其他环境，替代过去手写的 `world.config.mode === 'test'`。\n\n**注意**：不要再在 context 上挂全局 `tx`（启动时统一提交事务的写法容易出问题）。事务由调用方通过 `context.db.transaction(async (tx) => { ... })` 显式获取并传递 `tx` 对象；跨事件传递事务时，由事件创建者把 `tx` 放进事件 data 中。\n\n#### Redis 连接\n\n```ts\n// /app/bootstrap/redis/index.ts\nimport Redis from 'ioredis';\n\nexport const loadRedis = async (world: MilkioWorld<typeof generated>) => {\n  const redis = new Redis(world.config.redis.url);\n\n  world.on('milkio:executeBefore', async (event) => {\n    event.context.redis = createRedisHelper(redis);\n  });\n};\n```\n\n## 模块级 Bootstrap（$bootstraps）\n\n模块级 Bootstrap 放在模块的 `$bootstraps` 目录下，用于实现模块专属的启动逻辑，通常是认证中间件等。\n\n### 目录结构\n\n```\napp/modules/user/\n├── $bootstraps/\n│   └── user-auth.ts     # 用户认证引导\n├── $caches/\n├── $databases/\n└── ...\n```\n\n### 示例：用户认证中间件\n\n```ts\n// /app/modules/user/$bootstraps/user-auth.ts\nimport { type MilkioWorld } from 'milkio';\nimport type { generated } from '../../../../.milkio/index.ts';\n\nexport const loadUserAuth = async (world: MilkioWorld<typeof generated>) => {\n  world.on('milkio:executeBefore', async (event) => {\n    const authorization = event.context.http.request.headers.get('authorization');\n    const accessToken = (authorization ?? '').slice(7); // \"Bearer \".length\n\n    if (!accessToken || accessToken.length !== 64) {\n      // 未携带 Token\n      event.context.userProperties = [{ key: 'guest', permanent: true, id: ':guest' }];\n      if (event.meta.allow && event.meta.allow.includes('guest')) return;\n\n      // 测试环境放通\n      if (world.config.mode === 'test') {\n        console.log('⚠️ 该接口需登录，但未在请求中传递 token，测试环境下请求放通');\n        return;\n      }\n\n      throw event.fail('LOGIN_REQUIRED', undefined);\n    }\n\n    // 通过 Token 查询用户信息...\n    const user = await getUserByToken(event.context, accessToken);\n    if (!user) {\n      throw event.fail('INVALID_TOKEN', undefined);\n    }\n\n    event.context.userDevice = user.userDevice;\n    event.context.userProperties = user.properties;\n  });\n};\n```\n\n### 关键要点\n\n1. **`milkio:executeBefore` 事件**：模块级 Bootstrap 通常通过监听此事件实现请求拦截。\n2. **`event.context`**：可以在 context 上挂载自定义属性（如 `userDevice`、`userProperties`），后续 action 中可通过 `context.userDevice` 等访问。\n3. **`event.meta.allow`**：action 的 `meta.allow` 数组用于声明允许的访问方式（如 `['guest']` 表示允许未登录访问）。\n4. **`event.fail()`**：认证失败时使用 `event.fail()` 抛出错误，与 action 中的 `context.fail()` 用法相同。\n\n## 全局 Bootstrap vs 模块级 Bootstrap\n\n| 维度 | 全局 Bootstrap | 模块级 Bootstrap |\n|------|---------------|-----------------|\n| 位置 | `app/bootstrap/` | `app/modules/{模块}/$bootstraps/` |\n| 注册 | 在 `index.ts` 的 `bootstraps` 数组中 | 同样在 `index.ts` 的 `bootstraps` 数组中 |\n| 用途 | 基础设施（数据库、Redis、日志） | 业务中间件（认证、权限） |\n| 作用域 | 全局 | 通常只关注特定模块的逻辑 |\n| 典型示例 | Drizzle、Redis、CDN 配置、签名验证 | 用户认证 |\n\n## 可用的事件钩子\n\nBootstrap 中可以监听以下 Milkio 框架事件：\n\n| 事件名 | 触发时机 | 常见用途 |\n|--------|---------|---------|\n| `milkio:executeBefore` | 每个 API 请求执行前 | 认证、注入 context 属性 |\n| `milkio:httpRequest` | HTTP 请求到达时 | 日志、限流 |\n| `milkio:httpResponse` | HTTP 响应发送前 | 日志、响应头修改 |\n\n## 最佳实践\n\n1. **顺序很重要**：全局 Bootstrap 的注册顺序决定了初始化顺序和事件监听优先级。\n2. **测试环境放通**：认证 Bootstrap 应在测试环境下放通请求，方便测试。\n3. **错误提前抛出**：在 `milkio:executeBefore` 中发现不合法请求时，应立即 `throw event.fail()`，不要让请求继续执行。\n4. **context 挂载**：通过在 context 上挂载属性（如 `context.userDevice`），可以在后续的 action 中直接使用，避免重复查询。\n",
    "docs/cache.md": "# 缓存\n\n## 什么是缓存\n\nMilkio 提供进程内缓存功能，值原样存放在内存里，不做任何序列化。\n\n在分布式环境下，每个 pod 都有自己独立的堆，缓存之间无法共享互不共享。它的用途更多是减轻数据库压力：挡住高频点查、把重复的写入合并成低频写入。需要幂等或锁的场景，依赖数据库自身的原子性来实现。\n\n## 如何使用\n\n缓存定义在模块的 `$caches` 目录下，文件名采用 `*.cache.ts` 格式。\n\n### Key-Value 缓存\n\n外部主动写入、按 key 读取。\n\n```ts\n// /app/modules/message/$caches/api-token-last-used.cache.ts\nimport { defineMilkioKVCache } from 'milkio';\n\nexport type ApiTokenLastUsedCache = boolean;\n\nexport const apiTokenLastUsedCache = defineMilkioKVCache<ApiTokenLastUsedCache>({\n  expireMs: 60 * 60 * 1000, // 必填；永不过期必须显式传 null\n  maxEntries: 8192, // 必填；条目数上限，超出按 LRU 淘汰\n  intervalMs: 128, // 必填；本表的主动清理间隔，最小 128\n});\n```\n\n```ts\napiTokenLastUsedCache.get(key); // 未命中返回 undefined（与 drizzle 的 findFirst 对齐）\napiTokenLastUsedCache.set(key, value); // 返回写入的值\napiTokenLastUsedCache.setIfAbsent(key, value); // key 不存在或已过期时写入并返回 true\napiTokenLastUsedCache.has(key);\napiTokenLastUsedCache.delete(key);\napiTokenLastUsedCache.pull(key); // 读取并删除\napiTokenLastUsedCache.clear();\napiTokenLastUsedCache.size();\n```\n\nkey 只支持 `string`。\n\n### 结果缓存\n\n缓存函数的结果。同一 key 的并发调用时，会获得同一个 Promise，不会重复回源。函数出现异常时，会原样抛出，错误不会缓存。\n\n```ts\nimport { defineMilkioMemoCache } from 'milkio';\n\nexport type ApplicationCache = Awaited<ReturnType<typeof loadApplication>> | undefined;\n\nexport const applicationCache = defineMilkioMemoCache<ApplicationCache>({\n  expireMs: 30 * 60 * 1000,\n  maxEntries: 4096,\n  intervalMs: 1000,\n});\n```\n\n```ts\nconst application = await applicationCache.run(applicationId, async () => {\n  return await context.db.query.applicationTable.findFirst({ ... });\n});\n```\n\n### 布隆过滤器\n\n快速判断某些数据是否大概率不存在。\n\n```ts\nimport { defineMilkioBloomFilter } from 'milkio';\n\nexport const visitedNoteFilter = defineMilkioBloomFilter({\n  expectedEntries: 100_000,\n  falsePositiveRate: 0.01,\n});\n\nvisitedNoteFilter.add(noteId);\nvisitedNoteFilter.mightContain(noteId); // true 只代表「可能存在」\nvisitedNoteFilter.clear();\nvisitedNoteFilter.estimatedCount();\n```\n\n位图整体固定大小，无 TTL、无逐出。超过 `expectedEntries` 后误判率会上升。**需要强正确性的判定不要用布隆过滤器**。\n\n## 内存水位\n\n如果用户明确需要限制内存的使用时，可以在 `createWorld` 的顶层参数里选择性地传入全局内存水位（单位字节）：\n\n```ts\nconst world = await createWorld(generated, configSchema, {\n  memoryLimitBytes: 512 * 1024 * 1024,\n});\n```\n\n水位比较的是当前进程的 `process.memoryUsage().heapUsed`（V8 堆已用），不是缓存自身的占用。到达单表 `maxEntries` 限制或者总体内存超过水位限制后，缓存会跨表按 LRU 渐进逐出，有可能会逐出较少使用但仍在有效期内的 key。\n\n## 关于 Redis\n\n通常情况下，Milkio 工程运行在 Kubernetes 或者 Edgeone Markers、Cloudflare Workers 这些分布式环境中。除非必要，否则，不要建议用户引入 Redis。\n\n- 数据库还没有成为性能瓶颈时，Redis 在索引点查场景下只能带来毫秒级的性能优势\n- 这些优势的代价是：牺牲数据一致性、受限的查询语法、数据被限制在纯内存中、以及额外的序列化与网络往返\n- 针对 Edgeone Markers、Cloudflare Workers 等场景，Redis 只能在公网之间进行通信，性能优势会进一步被削弱\n\n绝大多数需求，二级缓存 + 数据库本身就已经足够。除非当数据库成为瓶颈，且无法靠扩容只读节点来缓解时，并且需求本身适合缓存时，才需要重新评估；届时 Redis 的价值也主要来自「跨实例共享状态 / 订阅发布 / 分布式锁」，而不是「缓存」这件事本身。如果用户要求你使用 Redis，你需要先思考架构是否合理，并向用户解释 Redis 的局限性。不过，如果用户要求你采用 Redis 时，你必须以用户需求为准。\n",
    "docs/config.md": "# Config\r\n\r\n## 基于环境的 Config 文件\r\n\r\n在 Milkio 中，Config 文件名即环境声明——不同环境的配置通过不同文件区分，而非写在同一个文件里。\r\n\r\n| 文件名                  | 生效环境 | 说明                 |\r\n| ----------------------- | -------- | -------------------- |\r\n| `common.config.ts`      | 所有环境 | 通用配置，优先级最低 |\r\n| `test.config.ts`        | 测试环境 | 仅测试环境生效       |\r\n| `{mode}.config.ts`      | 对应模式 | 仅对应 Cookbook 模式生效 |\r\n\r\n`common.config.ts` 优先级最低，当与其他环境配置存在同名键时，会被覆盖。\r\n\r\n### 模式与文件名对应关系\r\n\r\n项目通过 `VITE_MODE` 环境变量区分不同运行模式，配置文件名与模式名严格对应。例如：\r\n\r\n| VITE_MODE 值 | 对应的配置文件名 |\r\n| ----------------- | ---------------- |\r\n| `test` | `test.config.ts` |\r\n| `dvlp-zh-cn` | `dvlp-zh-cn.config.ts` |\r\n| `dvlp-en` | `dvlp-en.config.ts` |\r\n| `prod-zh-cn` | `prod-zh-cn.config.ts` |\r\n| `prod-en` | `prod-en.config.ts` |\r\n\r\n即：如果你要为 `dvlp-zh-cn` 模式编写专属配置，就创建 `dvlp-zh-cn.config.ts`；为 `prod-en` 编写，就创建 `prod-en.config.ts`。文件名就是模式名加 `.config.ts`。\r\n\r\n## 编辑配置\r\n\r\n### 全局配置\r\n\r\n全局配置文件位于项目根目录的 `configs/` 目录下。\r\n\r\n```typescript\r\n// /configs/common.config.ts\r\nimport { config } from 'milkio';\r\nexport default config(() => ({\r\n    database: {\r\n        host: 'localhost',\r\n        port: 3306,\r\n        user: 'root',\r\n        password: '<PASSWORD>',\r\n    },\r\n}));\r\n```\r\n\r\n### 模块内配置\r\n\r\nMilkio 支持在**任意模块内**定义专属的 Config 文件，这些配置会被自动加载。这样做的好处是：配置的作用域清晰可见——哪些配置只属于这个模块一目了然，更便于拆分与重构。\r\n\r\n模块配置文件位于模块目录下的 `$configs/` 目录下。\r\n\r\n**示例：**\r\n```typescript\r\n// /app/modules/shop/$configs/common.config.ts\r\nimport { config } from 'milkio';\r\n\r\nexport default config(() => ({\r\n    shopFileUpload: {\r\n        pageSize: 20,\r\n        maxUploadSize: 10 * 1024 * 1024, // 10MB\r\n        allowedFileTypes: ['jpg', 'png', 'gif', 'webp'],\r\n    }\r\n}));\r\n```\r\n\r\n注意，配置最好只导出一个对象，不要导出很多个宽泛的名称，很容易造成相互覆盖。\r\n\r\n## 在代码中访问配置\r\n\r\n在 Milkio 的 handler、action 等文件中，通过 `context.config` 访问配置。\r\n\r\n### 在 Handler 中使用配置：\r\n\r\n```typescript\r\n// /app/modules/shop/$handlers/handle-order.handler.ts\r\nimport type { MilkioWorld } from 'milkio';\r\nimport type { generated } from '../../../../.milkio/index.ts';\r\n\r\nexport default (world: MilkioWorld<typeof generated>) => {\r\n  world.on('order:validate', async ({ data, tx, context, fromModule }) => {\r\n    if (fromModule !== 'shop') return;\r\n\r\n    if (data.attachmentSize > context.config.shopFileUpload.maxUploadSize) {\r\n      context.logger.error('附件大小超出限制', JSON.stringify({ size: data.attachmentSize, max: context.config.shopFileUpload.maxUploadSize }));\r\n      throw context.fail('FILE_TOO_LARGE', undefined);\r\n    }\r\n\r\n    if (data.attachmentType && !context.config.shopFileUpload.allowedFileTypes.includes(data.attachmentType)) {\r\n      context.logger.error('不支持的文件类型', JSON.stringify({ type: data.attachmentType }));\r\n      throw context.fail('INVALID_FILE_TYPE', undefined);\r\n    }\r\n\r\n    // ... 更多代码\r\n  });\r\n};\r\n```\r\n\r\n### 在 Action 中使用配置：\r\n\r\n```typescript\r\n// /app/modules/shop/actions/list-products.action.ts\r\nimport { action } from 'milkio';\r\n\r\nexport default action({\r\n  async handler(context) {\r\n    // 访问全局配置\r\n    const baseUrl = context.config.baseUrl;\r\n\r\n    // 访问模块配置\r\n    const pageSize = context.config.pageSize;\r\n\r\n    return {\r\n      baseUrl,\r\n      pageSize,\r\n    };\r\n  },\r\n});\r\n```\r\n\r\n## .env 文件\r\n\r\n某些运行时支持 `.env` 文件自动加载环境变量，例如 Bun。\r\n\r\n但 `.env` 缺乏类型定义，无法直观看出项目依赖哪些变量。因此，`.env` 的定位应是 config 的上游——环境变量提供原始值，config 负责类型化与默认值兜底。\r\n\r\n```typescript\r\n// 在 config 中使用环境变量\r\nbaseUrl: env.BASE_URL ?? 'http://localhost';\r\n```\r\n\r\n若环境变量未设置，则使用配置中的默认值。\r\n\r\n## 重要注意事项\r\n\r\n1. **不要直接导入配置文件**：始终通过 `context.config` 访问配置，以确保配置的正确合并与类型安全\r\n2. **类型安全**：Milkio 会自动为配置生成类型，你可以获得完整的 TypeScript 类型提示\r\n3. **配置文件位置**：全局配置在 `configs/`，模块配置在模块的 `$configs/` 目录\r\n4. **命名规范**：配置文件必须以 `.config.ts` 结尾\r\n5. **不要在配置文件外部硬编码配置数据**\r\n",
    "docs/create-stargate.md": "# Create Stargate\r\n\r\nStargate 是 Milkio 的客户端通信 SDK。每个需要与 Milkio 后端通信的工程，都需要创建一个 stargate 实例。\r\n\r\n**重要**：stargate 实例仅供 embed（前端状态管理器）和 server（后端服务器）等 Milkio 工程内部使用。**前端 vue 工程（如 `kecream-app`）不得直接使用 stargate 调用 server 端点**，必须通过 `aurora.ipc.execute` 调用 embed 端点来间接通信。详见 SKILL.md 中\"前端必须通过 embed 与后端通信\"章节。\r\n\r\n## 创建实例\r\n\r\n```ts\r\n// /app/utils/stargate.ts\r\nimport type { generated } from '../../../todo-server/.milkio';\r\n\r\nexport const stargate = await createStargate<typeof generated>({\r\n  baseUrl: 'http://localhost:9000',\r\n});\r\n```\r\n\r\n### 配置项\r\n\r\n| 参数 | 类型 | 必填 | 说明 |\r\n|------|------|------|------|\r\n| `baseUrl` | `string \\| (() => string) \\| (() => Promise<string>)` | 是 | 后端服务地址，支持函数形式（可用于延迟计算） |\r\n| `timeout` | `number` | 否 | 请求超时时间（毫秒），默认 `6000` |\r\n| `fetch` | `typeof fetch` | 否 | 自定义 fetch 实现，用于非浏览器环境 |\r\n| `abort` | `typeof AbortController` | 否 | 自定义 AbortController 实现 |\r\n| `cacheStorage` | `CacheStorage` | 否 | 自定义缓存存储，配合 `cacheStrategy` 使用 |\r\n| `cacheEncryption` | `boolean` | 否 | 是否启用缓存加密，默认使用 AES-CTR |\r\n\r\n### baseUrl 动态配置\r\n\r\n在实际项目中，`baseUrl` 通常需要根据运行环境动态确定：\r\n\r\n```ts\r\nconst isClient = typeof window !== 'undefined';\r\n\r\nexport const stargate = await createStargate<typeof generated>({\r\n  baseUrl: (() => {\r\n    if (import.meta.env.MODE === 'prod-zh-cn' && isClient) return 'https://zh-cn.server.example.com';\r\n    if (import.meta.env.MODE === 'prod-zh-cn' && !isClient) return 'https://internal-api.example.com';\r\n    if (import.meta.env.MODE?.startsWith('prod-') && isClient) return 'https://en.server.example.com';\r\n    return 'http://localhost:9000';\r\n  })(),\r\n});\r\n```\r\n\r\n## 事件钩子\r\n\r\nStargate 提供三个事件钩子，用于在请求的不同阶段进行拦截处理。\r\n\r\n### `milkio:executeBefore`\r\n\r\n请求执行前触发，可用于添加通用请求头：\r\n\r\n```ts\r\nstargate.on('milkio:executeBefore', async (event) => {\r\n  // event.path: 请求路径\r\n  // event.options.headers: 请求头对象\r\n  event.options.headers['X-Custom-Header'] = 'value';\r\n});\r\n```\r\n\r\n### `milkio:fetchBefore`\r\n\r\n实际发送 HTTP 请求前触发，此时请求体（body）已序列化完毕，可用于签名等操作：\r\n\r\n```ts\r\nconst headerPrefix = 'Milkio';\r\n\r\nstargate.on('milkio:fetchBefore', async (event) => {\r\n  const timestamp = Date.now();\r\n  event.options.headers[`${headerPrefix}-Timestamp`] = `${timestamp}`;\r\n\r\n  // 添加 Authorization 头\r\n  const accessToken = await getAccessToken();\r\n  if (accessToken) {\r\n    event.options.headers['Authorization'] = `Bearer ${accessToken}`;\r\n  }\r\n\r\n  // 生成签名\r\n  const signContent = `${timestamp}#${event.path}#${event.body}#${signQuery}`;\r\n  const signature = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(signContent));\r\n  event.options.headers[`${headerPrefix}-Signature`] = /* 签名结果 */;\r\n});\r\n```\r\n\r\n### `milkio:executeError`\r\n\r\n请求执行出错时触发，可用于统一的错误处理（如登录过期跳转）：\r\n\r\n```ts\r\nstargate.on('milkio:executeError', async (event) => {\r\n  // event.path: 请求路径\r\n  // event.failure: failure 对象（{ $milkioFailure, kind: 'fail' | 'fault', code, data }）\r\n  // event.handleError: 错误处理辅助函数\r\n\r\n  // fault 是意料外错误，只有通用 code，不要用业务码匹配它\r\n  if (event.failure.kind !== 'fail') return;\r\n\r\n  if (event.failure.code === 'INVALID_TOKEN' || event.failure.code === 'LOGIN_REQUIRED') {\r\n    // 处理登录过期...\r\n    await logout();\r\n    return;\r\n  }\r\n\r\n  // 使用 handleError 处理特定失败码：只匹配 kind === 'fail' 且 code 相等的 failure\r\n  await event.handleError(event.failure, 'SPECIFIC_ERROR', (data) => {\r\n    // data 是该 fail-code 的类型化 data\r\n    handleSpecificError(data);\r\n    return true;\r\n  });\r\n});\r\n```\r\n\r\n## 缓存策略\r\n\r\n`stargate.execute` 的 `cacheStrategy` 选项支持三种模式：\r\n\r\n| 策略 | 说明 |\r\n|------|------|\r\n| `'off'`（默认） | 不使用缓存 |\r\n| `'fallback'` | 网络请求失败时回退到缓存数据 |\r\n| `'throttle'` | 在 `cacheThrottleMs` 毫秒内直接返回缓存，过期后重新请求 |\r\n\r\n使用示例：\r\n\r\n```ts\r\nconst [error, result, details] = await stargate.execute('/user/read-my', {\r\n  cacheStrategy: 'throttle',\r\n  cacheThrottleMs: 5000,\r\n  onCacheHit: (cachedResult) => {\r\n    // 缓存命中时回调，可用于乐观更新 UI\r\n  },\r\n});\r\n```\r\n\r\n如果需要自定义缓存存储（默认使用 IndexedDB），可以在创建 stargate 时传入 `cacheStorage`：\r\n\r\n```ts\r\nconst stargate = await createStargate<typeof generated>({\r\n  baseUrl: 'http://localhost:9000',\r\n  cacheStorage: {\r\n    get: async (key) => { /* 返回 { data, timestamp } 或 null */ },\r\n    set: async (key, data) => { /* 存储数据 */ },\r\n  },\r\n  cacheEncryption: true, // 启用缓存加密\r\n});\r\n```\r\n\r\n## 重试策略\r\n\r\n通过 `retryStrategy` 选项配置网络错误时的自动重试：\r\n\r\n```ts\r\nconst [error, result, details] = await stargate.execute('/user/read-my', {\r\n  retryStrategy: true, // 默认重试 2 次\r\n  // 或指定具体次数\r\n  // retryStrategy: 3,\r\n});\r\n```\r\n\r\n仅在**网络错误**时重试，业务错误（如 `DATA_NOT_FOUND`）不会触发重试；超时（`REQUEST_TIMEOUT`）同样不重试。\r\n\r\n## 超时\r\n\r\n`timeout` 对 action、stream、ping 都生效，默认 `6000` 毫秒。单次调用可覆盖实例默认值：\r\n\r\n```ts\r\nconst stargate = await createStargate<typeof generated>({\r\n  baseUrl: 'http://localhost:9000',\r\n  timeout: 6000,\r\n});\r\n\r\n// 单次请求放宽到 30 秒\r\nconst [failure, result] = await stargate.execute('/long-running/action', {\r\n  params: {},\r\n  timeout: 30_000,\r\n});\r\n```\r\n\r\n超时后 `execute` 返回 `{ $milkioFailure: true, kind: 'fault', code: 'REQUEST_TIMEOUT', data: { timeout, message } }`，并会 abort 底层请求。\r\n\r\n## Ping 方法\r\n\r\n`stargate.ping()` 用于检测与服务端的连通性和延迟：\r\n\r\n```ts\r\nconst [error, result] = await stargate.ping();\r\n\r\nif (error) {\r\n  console.log('连接失败', error.error);\r\n} else {\r\n  console.log('连接成功，延迟', result.delay, 'ms');\r\n  console.log('服务器时间戳', result.serverTimestamp);\r\n}\r\n```\r\n\r\n## 类型工具\r\n\r\n`stargate.$types` 提供了完整的类型信息，可用于泛型约束等场景：\r\n\r\n```ts\r\ntype Paths = keyof stargate.$types.generated['routeSchema'];\r\ntype ParamsOf<P extends Paths> = stargate.$types.params[P];\r\ntype ResultOf<P extends Paths> = stargate.$types.results[P];\r\ntype ErrorCode = stargate.$types.failure;\r\n```\r\n\r\n## 多 Stargate 实例\r\n\r\n当项目需要同时与多个后端通信时，可以创建多个 stargate 实例。例如，主应用同时与云端后端和 Electron 主进程通信：\r\n\r\n```ts\r\n// 主 stargate（与云端后端通信）\r\nexport const stargate = await createStargate<typeof generated>({\r\n  baseUrl: 'https://zh-cn.server.example.com',\r\n});\r\n\r\n// Electron stargate（与 Electron 主进程通信）\r\nexport const electronStargate = await createStargate<typeof electronGenerated>({\r\n  baseUrl: 'http://localhost:9006',\r\n});\r\n```\r\n",
    "docs/drizzle.md": "# Drizzle\n\n## @milkio/drizzle 工具集\n\n`@milkio/drizzle` 是一个**极简工具集**（不包装 drizzle-orm、不隐藏实现细节），只提供测试随机数据库相关的基础设施。连接、迁移、seed、删库、挂载 `context.db` 的代码都在你自己工程的样板里，可自由修改。\n\n**导出的纯函数 / 常量：**\n\n| 导出 | 说明 |\n|------|------|\n| `TEST_DATABASE_PREFIX` | 测试库名前缀 `milkio_test`（启动清理时按此前缀 DROP） |\n| `TEST_DATABASE_HEADER` | 请求头名 `x-milkio-test-db`，astra 与 server 共享同一约定 |\n| `TEST_DATABASE_MAX_LENGTH` | 数据库名最大长度（64） |\n| `generateTestDatabaseId(filePath?)` | 生成 `milkio_test_<文件片段>_<随机>`，≤64 字符 |\n| `sanitizeDatabasePart(input)` | 清洗标识符为合法库名片段 |\n| `withTestDatabase(url, databaseId)` | 替换 URL 的数据库名；`databaseId` 为空时原样返回 |\n| `extractDatabaseName(url)` | 从 URL 提取数据库名 |\n| `getTestDatabaseId(headers)` | 从请求头读取随机库名，无则返回 `null`（走默认库） |\n\n**随机库名带测试文件路径**，例如 `app/modules/oc/__TEST__.test.ts` → `milkio_test_oc_test_a1b2c3d4`，便于追溯是哪个测试文件创建了该库。\n\n### 测试基建：cleanDatabase 钩子\n\n`@milkio/astra` 的 `world.cleanDatabase()` 被标准化为**钩子调度器**：每次显式调用都会**新建一个随机库并切换**，然后并行执行所有通过 `hooks.onCleanDatabase(...)` 注册的钩子（从黄金库克隆 DDL + seed、清 Redis 命名空间等）。**每次运行测试前**，globalSetup 会先把上一次遗留的 `milkio_test_*` 库全部删掉。\n\n`@milkio/drizzle` 与 `@milkio/redis` **都不在包内提供 hook 默认实现**；hook 是样板代码，写在你项目的 `app/utils/drizzle-test.ts` / `redis-test.ts` 中，可自由修改。\n\n```ts\n// app/utils/astra.ts\nimport { fileURLToPath } from 'node:url';\nimport { createAstra } from '@milkio/astra';\nimport { drizzleCleanHook } from './drizzle-test.ts';\nimport { redisCleanHook } from './redis-test.ts';\n\nexport const astra = await createAstra({\n  stargate,\n  bootstrap: async (hooks) => {\n    hooks.onCleanDatabase(drizzleCleanHook({                  // 建库+迁移+seed\n      baseUrl: () => testConfig.drizzle.url,\n      migrationsFolder: fileURLToPath(new URL('../../drizzle', import.meta.url)),\n    }));\n    hooks.onCleanDatabase(redisCleanHook({ url: () => testConfig.redis.url }));\n    return {};\n  },\n});\n```\n\n**每次运行测试前**删除上一次遗留的 `milkio_test_*` 库，必须放在 vitest `globalSetup`（每次运行只执行一次），**不能放在每个测试文件的 astra bootstrap 里**——并行运行时后启动的文件会把先启动文件正在使用的库删掉。`globalSetup` 还负责准备「黄金库」：完整迁移在这里只跑一次，之后每个测试库直接克隆黄金库的 DDL（`CREATE TABLE ... LIKE`），几秒内即可建好一个全新随机库，避免每个测试都重放几十个迁移文件（本机实测单次完整迁移约 40s）：\n\n```ts\n// app/utils/astra-global-setup.ts（在 vitest.config.ts 的 globalSetup 注册）\nimport { fileURLToPath } from 'node:url';\nimport { dropAllTestDatabases, ensureGoldenDatabase } from './drizzle-test.ts';\nimport { flushTestRedis } from './redis-test.ts';\n\nexport default async function setup() {\n  await dropAllTestDatabases(testConfig.drizzle.url);\n  await flushTestRedis(testConfig.redis.url);\n  await ensureGoldenDatabase({\n    baseUrl: testConfig.drizzle.url,\n    migrationsFolder: fileURLToPath(new URL('../../drizzle', import.meta.url)),\n    force: true,\n  });\n}\n```\n\n测试代码里照常使用，无需改动：\n\n```ts\nconst [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\nawait world.cleanDatabase();   // 新建随机库 + 完整迁移 + seed + 清当前库 redis 命名空间\n```\n\n由于每个测试用各自独立的随机库，文件之间互不干扰，可以安全地并行运行（在 `vitest.config.ts` 中放开 `fileParallelism` / `maxWorkers`）。\n\n**测试文件里直连数据库 / redis 时**（绕过 HTTP 直接断言行数据），也必须跟随当前随机库，不能连默认库。样板在 `drizzle-test.ts` 提供跟随当前库的 `db` 代理、`getCurrentTestDbUrl()`，在 `redis-test.ts` 提供 `testRedisKey(key)`（服务端测试模式下所有业务 key 带 `${databaseId}:` 前缀，redis 清理只按前缀删，绝不能 `flushDb`）：\n\n```ts\nimport { db } from '../../utils/drizzle-test.ts';\nimport { testRedisKey } from '../../utils/redis-test.ts';\n\nawait world.cleanDatabase();\nawait db.execute(sql`INSERT INTO ocItem ...`);           // 写入当前随机库\nawait redis.incrBy(testRedisKey(quotaKey), 999900);       // 写入当前库的 redis 命名空间\n```\n\n另外几点并行注意事项（样板已内置，改样板时不要回退）：\n\n- **完整迁移很慢**：几十个迁移文件单次重放可达数十秒（BaiduSync 等慢盘更甚），超过 vitest 默认 testTimeout 会让每个测试都超时。因此样板采用「黄金库」：globalSetup 里 `ensureGoldenDatabase({ force: true })` 完整迁移一次，`drizzleCleanHook` 里 `cloneGoldenDatabase()` 用 `CREATE TABLE ... LIKE` 克隆 DDL（几秒）再 seed。若你的迁移足够快，可改回每次完整迁移。\n- **MySQL 连接数**：`world.cleanDatabase()` 每次都切到新库，服务端按 URL 懒建的连接只增不减会撞 `max_connections`（Too many connections）。样板在 bootstrap/drizzle 里给缓存连接加了 LRU 上限；淘汰时**不能 `await end()`**——被淘汰的连接可能仍有请求在途（测试超时后请求还在服务端跑），`await` 会把当前请求挂起。\n- **磁盘占用**：分区表克隆每库可达 100MB+（每分区独立 .ibd），一轮 co test 约 200 个库 ≈ 20GB，小磁盘直接撑爆。样板采用**切库即删**：`drizzleCleanHook` 每次切换新库时删除上一个测试库，同时存在的测试库数量 = 并行测试文件数（个位数）；globalSetup teardown 再兜底清理文件结束后的最后一个库与黄金库。\n- **migrationsFolder**：`migrate()` 的迁移目录按进程 cwd 解析，从 monorepo 根跑 vitest 时 `./drizzle` 会指错位置，必须用 `import.meta.url` 解析为绝对路径。\n\n完整的样板代码（含 `drizzleCleanHook` / `dropAllTestDatabases` / `truncateAll` 的可改实现）见 `template-milkio` 模板的 `app/utils/drizzle-test.ts`。\n\n## 示例\n\n```ts\n// 获取一条\nconst user = await db.query.user.findFirst();\n// 获取多条\nconst users = await db.query.user.findMany();\n// 筛选条件\nconst users = await db.query.user.findMany({\n    where: and(\n        eq(userTable.id, 1),\n        eq(userTable.name, \"张三\"),\n    ),\n});\n// 排序\nconst users = await db.query.user.findMany({\n    orderBy: [asc(userTable.id)],\n});\n```\n\n使用 drizzle 时，请优先使用 db.query.<表名>.findMany(...) 这种方式来查询。除非必要，否则尽可能不要使用 `await db.select(...).from(...)` 的形式进行查询。\n\n## 事务\n\n可以通过 `await context.db.transaction((tx) => { ... })` 开启事务。事务应尽量简短，不要把整个方法包裹在事务中，尤其不要将查询语句纳入事务。**单条插入、更新、删除无需事务，只有需要同时执行两条及以上写操作时才使用。**\n\n如果事务内的操作没有顺序依赖，可以用 `Promise.all` 并行执行：\n\n```ts\nawait context.db.transaction((tx) => Promise.all([\n    tx.insert(storageAssetTable).values({\n        id: assetId,\n        storageId: storageId,\n    }),\n    tx.insert(storageTable).values({\n        id: storageId,\n        spaceId: params.data.spaceId,\n    }),\n]));\n```\n\n## 乐观锁\n\n所有 `edit` 端点必须使用乐观锁，防止并发更新导致数据覆盖。\n\n原理：将读取时的 `updatedAt` 作为更新条件，若期间有其他请求修改了该行，`updatedAt` 已变化，更新影响 0 行即检测到冲突。\n\n```ts\nconst result = await context.db.update(articleTable).set({ ...params.data, updatedAt: undefined }).where(\n  and(\n    eq(articleTable.id, params.data.id),\n    eq(articleTable.updatedAt, params.data.updatedAt),\n  )\n);\nif (result[0].affectedRows === 0) throw context.fail(\"DATA_CONFLICT\", undefined);\n```\n\n不要将 `updatedAt` 包含在 `.set()` 中——MySQL 的 `ON UPDATE CURRENT_TIMESTAMP(3)` 仅在该列未出现于 SET 子句时自动生效，显式传入会导致时间戳不会更新。\n\n## 数据库表\n\n所有数据库表文件均存放在模块的 `$databases` 目录下。\n\n我们使用 drizzle 作为 ORM 工具。每个文件代表一张数据库表，采用小写字母+中划线命名，并使用单数名词。主表文件名必须与模块名严格一致。副表（如中间表、扩展表）的文件名需以模块名开头，中间表使用 `to` 连接相关表名。注意：**数据库中的实际表名需转换为驼峰命名**。例如：\n-   用户模块主表：`user.table.ts`（对应表 `user`）\n-   用户设备表：`user-device.table.ts`（对应表 `userDevice`）\n-   用户-设备中间表：`user-to-user-device.table.ts`（对应表 `userToUserDevice`）\n\n数据库表文件写法示例如下（**注意：使用 MySQL 作为数据库，因此，请使用 `drizzle-orm/mysql-core`，而非 `drizzle-orm/pg-core`**）：\n\n```typescript\n// /app/modules/application/$databases/application.table.ts\nimport type typia from \"typia\";\nimport { relations, sql } from \"drizzle-orm\";\nimport { char, int, datetime, mysqlTable, varchar } from \"drizzle-orm/mysql-core\";\nimport { user } from \"../../user/$databases/user.table.ts\";\n\n// 应用程序表\nconst tableName = \"application\";\n\nexport const applicationTable = mysqlTable(\n  tableName,\n  {\n    // 主键 ID，24位随机字符串\n    id: char({ length: 24 }).$type<string & typia.tags.Pattern<\"^[a-zA-Z0-9]{24}$\">>().notNull().primaryKey(),\n    // 用户 ID\n    userId: char({ length: 24 }).$type<string & typia.tags.Pattern<\"^[a-zA-Z0-9]{24}$\">>().notNull(),\n    // 名称\n    name: varchar({ length: 32 }).$type<string & typia.tags.Pattern<\"^\\\\S{2,32}$\">>().unique(),\n    // 创建时间\n    createdAt: datetime({ fsp: 3 }).notNull().default(sql`CURRENT_TIMESTAMP(3)`),\n    // 更新时间\n    updatedAt: datetime({ fsp: 3 }).notNull().default(sql`CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)`),\n  },\n  (t) => ([]),\n);\n\nexport const applicationRelations = relations(applicationTable, ({ one, many }) => ({\n  user: one(user, {\n    fields: [applicationTable.userId],\n    references: [user.id],\n  }),\n}));\n\nexport type Application = typeof applicationTable.$inferSelect;\nexport type ApplicationInsert = Omit<typeof applicationTable.$inferInsert, \"createdAt\" | \"updatedAt\">;\n```\n\n### 字段定义规范\n\n定义数据库表时，务必遵循以下规范。\n\n-   每张表必须包含 `createdAt` 和 `updatedAt` 字段。\n-   **字符串**：使用 `string & typia.tags.Pattern<\"<正则表达式>\">` 严格约束格式、长度和内容。\n-   **数字**：使用 `number & typia.tags.Minimum<>`、`Maximum<>`、`ExclusiveMaximum<>`、`ExclusiveMinimum<>`、`MultipleOf<>` 等标签约束。\n-   **布尔值**：使用 `boolean` 类型。\n-   **枚举值**：使用 `varchar` 类型，并通过 `.$type<\"foo\" | \"bar\" | \"baz\">()` 限制取值。\n-   **JSON**：定义普通的 TypeScript 类型。\n-   **时间**：一律使用 `datetime({ fsp: 3 })`，不附加额外类型。\n-   **价格**：使用 `int` 类型，单位为“分”。禁止使用 `bigint` 或小数类型。\n-   **主键**：固定为 24 位长度随机字符串：`id: char({ length: 24 }).$type<string & typia.tags.Pattern<\"^[a-zA-Z0-9]{24}$\">>().notNull().primaryKey()`。\n-   每个字段上方，都必须添加详细的说明其含义的注释，不可省略。\n\n\n\n### Typia 类型标签\n\n你可能注意到了，我们使用 typia 来约束可存入数据的类型。当数据库的类型被端点的 `Params` 所引用时，Milkio 会自动使用 typia 来确保接收到的值符合 `Params` 的类型。任何不符合你方法预期类型的输入都将被拒绝，而任何符合类型要求的额外属性将被移除。\n\n匹配正则表达式：\n\n```ts\nstring & typia.tags.Pattern<\"^[a-z]+$\">\n```\n\n限制字符串长度:\n\n```ts\nstring & typia.tags.MaxLength<3> & typia.tags.MinLength<191>\n```\n\n限制数组中的数量：\n\n```ts\nArray<string> & typia.tags.MinItems<3> & typia.tags.MaxItems<10>\n```\n\n限制数字为整数类型：\n\n```ts\nnumber & typia.tags.Type<\"uint32\">\nnumber & typia.tags.Type<\"int32\">\n```\n\n限制数字范围：\n\n```ts\nnumber & typia.tags.Minimum<0> & typia.tags.Maximum<100>\nnumber & typia.tags.ExclusiveMinimum<19> & typia.tags.Maximum<100>\n```\n\n数字必须是某数的倍数：\n\n```ts\nnumber & typia.tags.MultipleOf<5>\n```\n\n其他格式：\n\n```ts\nstring & typia.tags.Format<\"ipv4\">\nstring & typia.tags.Format<\"ipv6\">\nstring & typia.tags.Format<\"url\">\n```\n\n格式标签支持联合类型（允许匹配多种格式之一）：\n\n```ts\nstring & (typia.tags.Format<\"ipv4\"> | typia.tags.Format<\"ipv6\">)\n```\n\n数组元素去重：\n\n```ts\nArray<string> & typia.tags.UniqueItems\n```\n\n数组元素同时约束格式与数量：\n\n```ts\nArray<string & typia.tags.Format<\"uuid\">> & typia.tags.MinItems<1> & typia.tags.MaxItems<100>\n```\n\n注意，不要使用本文档未列出的类型标签，它们很可能是不存在的。\n\n### 定义表关系\n\n如果表之间存在关联，需定义关系（relations）。例如：\n-   **多对多关系（用户-角色）**：\n    在中间表 `user-to-role.table.ts` 末尾添加：\n    ```typescript\n    export const userToRoleRelations = relations(userToRole, ({ one, many }) => ({\n      user: one(user, {\n        fields: [userToRole.userId],\n        references: [user.id],\n      }),\n      role: one(role, {\n        fields: [userToRole.roleId],\n        references: [role.id],\n      }),\n    }));\n    ```\n    在 `user.table.ts` 和 `role.table.ts` 末尾分别添加 `many(userToRole)` 和 `many(roleToUser)` 关系。\n-   **一对多关系（文章-评论）**：\n    在 `article.table.ts` 末尾添加 `many(comment)` 关系。\n    在 `comment.table.ts` 末尾添加 `one(article)` 关系。\n\n**请使用相对路径引用其他数据库表，且不要为关系添加不必要的表引用。**\n\n## 索引\n\ndrizzle 使用表的第二个参数来定义索引。例如：\n\n```\nmysqlTable(\n  tableName,\n  {\n    // 字段定义...\n  },\n  (t) => ([ // 注意：此处是数组，只有在旧版中才是对象\n    index('index__userId').on(t.userId),\n  ])\n);\n```\n\n## 数据库迁移\n\n**由 AI 自己运行 `co drizzle`，无需用户执行。** `co drizzle` 默认**完全非交互**：不会弹出任何确认。只有一个候选 project / mode 时会自动选中；存在多个候选且未指定 `--project` / `--mode` 时会立即以退出码 3 失败并列出候选，不会等待输入。\n\n**禁止自行编写迁移 SQL 文件。** 修改表结构（如新增字段、索引、关系）后，只需在 `*.table.ts` 中声明变更，然后由你自己运行 `co drizzle generate` 生成迁移文件。不要手动创建或修改 `drizzle/` 目录下的 `.sql` 文件与 `_journal.json`。\n\n### 一条命令完成「生成迁移 + 应用迁移」\n\n```bash\nco drizzle generate --project=<项目名> --mode=<模式名> --yes --json\n```\n\n-   `--yes`：授权执行写数据库的操作（migrate，以及 generate 之后的自动 migrate）。不带 `--yes` 时，generate 只生成迁移文件、不应用迁移。\n-   项目若存在 `drizzle.migrate.ts`，generate 成功且带 `--yes` 时会自动执行它。\n-   不想自动应用迁移可加 `--no-auto-migrate`。\n\n### 其他命令\n\n-   `co drizzle migrate --project=<项目名> --mode=<模式名> --yes --json`：应用迁移。\n-   `co drizzle pull --project=<项目名> --mode=<模式名> --json`：从数据库内省 schema（不会提示）。\n-   `co drizzle push --project=<项目名> --mode=<模式名> --yes --json`：直接把 schema 推到数据库，属于高风险命令，必须带 `--yes`；若包含数据丢失语句（删表、删列等），还需额外 `--force`（或用 `--answers` 显式选择 `Yes`）。\n-   `co drizzle check --project=<项目名> --mode=<模式名> --json`：迁移后检查状态。\n-   `co drizzle export ...`：导出 SQL（可选）。\n\n### 输出与退出码\n\n带 `--json` 时，stdout 只有一个 JSON 文档，日志全部写在 stderr。结果字段：\n\n| 字段 | 说明 |\n|------|------|\n| `ok` | 是否成功 |\n| `status` | `generated` / `no_changes` / `migrated` / `pushed` / `introspected` / `checked` / `upgraded` / `exported` / `decisions_required` / `failed` |\n| `project` / `mode` / `database` | 本次操作的工程、模式、数据库（不含密码） |\n| `migrations` | `[{ tag, file, sql }]` |\n| `autoMigrate` | `{ ran, exitCode }` |\n| `decisions` / `fingerprint` / `resume` | 仅 `decisions_required` 时出现，见下节 |\n| `next` | 建议的下一步 |\n| `output` | `export` 时导出的 SQL 文本 |\n| `note` / `error` | 补充说明 / 失败原因 |\n\n退出码：\n\n-   `0`：成功或无需变更。\n-   `1`：失败。\n-   `2`：需要 AI 决策（此时未写入任何迁移文件）。\n-   `3`：参数 / 授权 / 项目 / mode 错误。\n-   `4`：并发锁冲突。\n\n### 退出码 2：需要 AI 决策\n\nschema 变更存在歧义时（典型：重命名列 / 表，drizzle-kit 分不清是 rename 还是 drop+create），命令不会卡住等待输入，而是以退出码 2 输出：\n\n```json\n{\n  \"ok\": false,\n  \"status\": \"decisions_required\",\n  \"command\": \"generate\",\n  \"project\": \"test\",\n  \"mode\": \"test\",\n  \"fingerprint\": \"bb99d84e5d42d35e\",\n  \"decisions\": [\n    {\n      \"index\": 0,\n      \"kind\": \"rename_or_create\",\n      \"entity\": \"column\",\n      \"question\": \"Is nickname column in user table created or renamed from another column?\",\n      \"options\": [\n        { \"index\": 0, \"label\": \"nickname\", \"choice\": \"create\" },\n        { \"index\": 1, \"label\": \"name › nickname\", \"choice\": \"rename\" }\n      ],\n      \"digest\": \"479ffdcc84f0\"\n    }\n  ],\n  \"resume\": \"co drizzle generate --project=test --mode=test --yes --json --answers='{\\\"fingerprint\\\":\\\"bb99d84e5d42d35e\\\",\\\"digests\\\":[\\\"479ffdcc84f0\\\"],\\\"choices\\\":[\\\"<option index>\\\"]}'\"\n}\n```\n\n处理流程：\n\n1. 读取 `decisions`，为每个问题按 `options[].index` 选一个选项（`choice` 字段说明了语义：`create` = 新建、`rename` = 重命名、`yes` / `no` = 确认或拒绝）。\n2. 把 `resume` 命令里尖括号占位符 `<option index>` 按提示顺序替换成对应的数字 index（例如重命名选 `1`，即 `\"choices\":[1]`），然后执行该命令即可一次成功。`resume` 会保留原命令的授权：原命令没有 `--yes` 时，resume 也不会带 `--yes`（不会因为重跑而自动应用迁移）。命令中的 `digests` 会逐个校验两次运行看到的是同一批问题；若不一致会再次以退出码 2 返回**新的** `decisions`（并带 `note` 提示），不会猜测作答。`fingerprint` 是整批决策的摘要，便于日志排查，不用于放行判断。\n3. 也可以直接自己拼 `--answers`：`--answers='{\"fingerprint\":\"<fingerprint>\",\"digests\":[\"<digest>\",...],\"choices\":[<index>,...]}'`。`digests` 与 `fingerprint` 可省略，但不建议省略（省略后不做一致性校验）。\n4. 已知会重命名时，可以一次成型（仅当恰好出现**一个**歧义提示时生效；出现第二个提示时仍会 exit 2 要求显式 answers，避免把 drop+create 误当成 rename）：\n\n```bash\nco drizzle generate --project=<项目名> --mode=<模式名> --yes --on-prompt=rename --json\n```\n\n**不要自己手写迁移 SQL，也不要修改 `drizzle/` 下的 `.sql` 或 `_journal.json` 来绕过决策。**\n\n### `--interactive` 仅人类使用\n\n`--interactive` 只给人类使用：显式开启后才会恢复 project / mode 选择与确认提示。AI 不要使用。\n\n### 涉及步骤\n\n1. 在 `*.table.ts` 中修改表定义（加字段、加索引、加关系等）。\n2. 自己运行 `co drizzle generate --project=<项目名> --mode=<模式名> --yes --json`，一次完成迁移文件的生成与应用。\n3. 按退出码处理：`0` 成功；`2` 走上面的决策流程；`3` / `4` 修正参数或稍后重试。\n\n## 重要注意事项\n\n1.  **禁止自行编写迁移 SQL 文件**，由 AI 自己运行 `co drizzle generate ...`（见上节）生成。\n2.  数据库表名称必须以模块名开头，或完全等于模块名。请勿省略模块名。\n3.  **禁止使用外键约束**。如需创建索引，请使用单字段索引。\n4.  严格遵循一个文件一张数据库表的原则，切勿在单个文件中编写多张表。\n\n在编写代码前，请先阐述你设计的数据库表之间的关系，供用户决策，然后再编写表结构代码。请务必仔细评估需求，考虑到可能需要创建多张表的场景。",
    "docs/events.md": "# Events\r\n\r\nMilkio 的事件系统是后端模块间通信的核心机制。模块之间不需要直接引用对方的代码，而是通过触发和监听事件来协作。事件系统支持三种触发模式——普通触发、全员审批和任意审批——使模块间既能广播通知，也能实现\"审批制\"的业务约束。\r\n\r\n## 文件规范\r\n\r\n### 事件定义\r\n\r\n事件定义文件命名为 `*.event.ts`，放置在模块的 `$events` 目录下。每个文件必须导出一个名为 `_` 的 interface，其键为事件名（字符串），值为事件数据类型：\r\n\r\n```\r\napp/modules/payment/\r\n├── $events/\r\n│   └── validate-payment.event.ts\r\n├── $handlers/\r\n├── add.action.ts\r\n└── ...\r\n```\r\n\r\n```ts\r\n// /app/modules/payment/$events/validate-payment.event.ts\r\nimport type { Payment, paymentTable } from '../$databases/payment.table.ts';\r\nimport type { MilkioContext } from '../../../../.milkio/declares.ts';\r\n\r\nexport interface _ {\r\n  /**\r\n   * 支付校验\r\n   * ⚠️ 一笔订单，必须订阅此事件，并显式地把 allow 改为 true，此支付才可以成功创建\r\n   */\r\n  'payment:validate': {\r\n    data: typeof paymentTable.$inferSelect & { allow: boolean };\r\n    fromModule: Payment['fromModule'];\r\n    context: MilkioContext;\r\n    tx: MilkioContext['db'];\r\n  };\r\n  /** 支付成功 */\r\n  'payment:paid': {\r\n    data: typeof paymentTable.$inferSelect;\r\n    fromModule: Payment['fromModule'];\r\n    context: MilkioContext;\r\n    tx: MilkioContext['db'];\r\n  };\r\n}\r\n```\r\n\r\n### 事件命名约定\r\n\r\n- **冒号分隔**：事件名使用冒号 `:` 作为命名空间分隔符，格式为 `模块名:动作`，如 `payment:validate`、`user:login`、`space:delete`\r\n- **`app:` 前缀**：以 `app:` 开头的事件会自动推送到前端（在 `watch.stream.ts` 中通过 `key.startsWith('app:')` 过滤）\r\n- **`life-cycle:` 前缀**：生命周期事件，由框架触发，用于初始化流程（如 `life-cycle:mounted`）\r\n- **`milkio:` 前缀**：框架内部事件，如 `milkio:executeBefore`、`milkio:httpRequest`、`milkio:httpResponse`\r\n- **其他前缀**：如 `payment:`、`user:`、`storage:`、`captcha:` 等，是服务端内部事件，不会推送到前端\r\n\r\n### 事件监听\r\n\r\n事件监听文件命名为 `*.handler.ts`，放置在模块的 `$handlers` 目录下。每个文件导出一个默认函数，接收 `world` 参数，通过 `world.on()` 注册事件监听：\r\n\r\n```ts\r\n// /app/modules/payment/$handlers/handle-payment.handler.ts\r\nimport type { MilkioWorld } from 'milkio';\r\nimport type { generated } from '../../../../.milkio/index.ts';\r\n\r\nexport default (world: MilkioWorld<typeof generated>) => {\r\n  world.on('payment:validate', async ({ data, tx, context, fromModule }) => {\r\n    // 只处理特定模块的支付\r\n    if (fromModule !== 'order') return;\r\n\r\n    // 校验金额、币种等...\r\n    if (data.amount !== 399) {\r\n      throw context.fail('PAYMENT_ADD_FAILED', undefined);\r\n    }\r\n\r\n    // ✅ 审批通过：显式设置 allow 为 true\r\n    data.allow = true;\r\n  });\r\n\r\n  world.on('payment:paid', async ({ data, tx, context, fromModule }) => {\r\n    if (fromModule !== 'order') return;\r\n    // 处理支付成功后的业务逻辑...\r\n  });\r\n};\r\n```\r\n\r\n## emit 的三种变体\r\n\r\n### `context.emit(key, value)` — 普通触发\r\n\r\n**返回值**：`Promise<void>`\r\n\r\n纯广播模式。触发事件后，所有监听该事件的 handler 都会被执行，但触发方不关心 handler 的返回值。\r\n\r\n```ts\r\n// 支付回调中，广播支付成功事件\r\nawait context.emit('payment:paid', {\r\n  data: payment,\r\n  fromModule: payment.fromModule,\r\n  context,\r\n  tx: context.db,\r\n});\r\n```\r\n\r\n```ts\r\n// 用户登录后，广播登录事件，由其他模块响应\r\nawait context.emit('user:login', { context, db: context.db, data: user });\r\n```\r\n\r\n普通 `emit` 适合\"通知型\"场景——事件触发后，订阅方各自执行自己的逻辑，触发方不需要知道结果。\r\n\r\n---\r\n\r\n### `context.emitAllApproved(key, value)` — 全员审批\r\n\r\n**返回值**：`Promise<boolean>`\r\n\r\n所有订阅了该事件的 handler 都必须返回 `true`（或不抛出异常），`emitAllApproved` 才返回 `true`。只要有**任何一个** handler 抛出异常，整个审批就会失败（抛出异常），`emitAllApproved` 不会返回 `false`——而是直接将异常向上抛出。\r\n\r\n这是最严格的审批模式，适用于**所有相关方都必须同意**的场景。\r\n\r\n```ts\r\n// 发送验证码前，必须通过验证码校验\r\nawait context.emitAllApproved('captcha:validate', { context, ...params.captcha });\r\n// 如果 captcha 模块的 handler 抛出异常，上面的代码也会抛出异常，后续逻辑不会执行\r\n```\r\n\r\n在项目中，`captcha:validate` 事件目前只有一个 handler，所以 `emitAllApproved` 和 `emitAnyApproved` 效果相同。但使用 `emitAllApproved` 的语义是：**所有**验证都必须通过，如果未来增加更多验证方式，它们全部通过才算通过。\r\n\r\n#### 审批模式的数据约定\r\n\r\n使用审批模式时，事件数据中通常包含一个 `allow` 字段。handler 通过将 `data.allow` 设为 `true` 来表示审批通过：\r\n\r\n```ts\r\n// 触发方\r\nconst emitData = {\r\n  data: { ...paymentData, allow: false },  // 初始 allow 为 false\r\n  fromModule: 'order',\r\n  context,\r\n  tx: context.db,\r\n};\r\n\r\n// ⚠️ 这里用普通 emit，然后手动检查 allow\r\nawait context.emit('payment:validate', emitData);\r\n\r\nif (!emitData.data.allow) {\r\n  throw context.fail('PAYMENT_ADD_FAILED', undefined);\r\n}\r\n```\r\n\r\n> **注意**：上面的 `payment:validate` 使用的是普通 `emit` + 手动检查 `allow` 的模式。这是因为 `payment:validate` 事件在 `emit` 期间可能需要修改 `data` 对象，触发方在 `emit` 返回后检查 `allow`。而 `emitAllApproved` / `emitAnyApproved` 则是直接通过返回值判断，handler 通过 `return true` 或设置 `data.allow = true` 来表示同意。\r\n\r\n---\r\n\r\n### `context.emitAnyApproved(key, value)` — 任意审批\r\n\r\n**返回值**：`Promise<boolean>`\r\n\r\n只要有**任意一个**订阅了该事件的 handler 返回 `true`（或将 `data.allow` 设为 `true`），`emitAnyApproved` 就返回 `true`。如果所有 handler 都没有返回 `true` 也没有设置 `data.allow = true`，则返回 `false`。\r\n\r\n与 `emitAllApproved` 不同，**单个 handler 抛出异常不会导致整体失败**——只要有一个 handler 审批通过即可。\r\n\r\n```ts\r\n// 下载鉴权：只要有任意一个模块允许下载即可\r\nconst allow = await context.emitAnyApproved('sync:akira-storage:download-validate', emitData);\r\nif (!allow) {\r\n  context.logger.error('鉴权未被通过', emitData);\r\n  throw context.fail('REQUEST_FAIL', undefined);\r\n}\r\n```\r\n\r\n`emitAnyApproved` 适合\"多鉴权源\"场景——多个模块可能都有权放行，只要有一个模块同意即可。\r\n\r\n---\r\n\r\n### 三种变体对比\r\n\r\n| 方法 | 返回值 | handler 抛异常时 | handler 返回 true 时 | 典型场景 |\r\n|------|--------|-----------------|---------------------|---------|\r\n| `emit` | `Promise<void>` | 异常向上抛出 | 忽略返回值 | 广播通知（登录、删除） |\r\n| `emitAllApproved` | `Promise<boolean>` | 整体失败，异常向上抛出 | 全部 true 才返回 true | 全员审批（验证码、支付校验） |\r\n| `emitAnyApproved` | `Promise<boolean>` | 不影响，继续检查其他 handler | 任一 true 即返回 true | 多源审批（下载鉴权） |\r\n\r\n---\r\n\r\n## 典型用法\r\n\r\n### 1. 广播通知 — 用户登录\r\n\r\n用户登录后，需要初始化空间、刷新缓存等，这些逻辑分散在不同模块中。通过 `user:login` 事件解耦：\r\n\r\n**定义事件** `$events/user.event.ts`：\r\n\r\n```ts\r\nexport interface _ {\r\n  'user:login': {\r\n    data: typeof userTable.$inferInsert;\r\n    context: MilkioContext;\r\n    db: MilkioContext['db'];\r\n  };\r\n}\r\n```\r\n\r\n**触发事件** `device/login/1-guest-login.action.ts`：\r\n\r\n```ts\r\nawait context.emit('user:login', { context, db: context.db, data: user });\r\n```\r\n\r\n**监听事件** `space/$handlers/init-space.handler.ts`：\r\n\r\n```ts\r\nexport default (world: MilkioWorld<typeof generated>) => {\r\n  world.on('user:login', async ({ data, db, context }) => {\r\n    // 为用户初始化默认空间\r\n    const usrId = `usr:${data.id}`;\r\n    // ...创建空间...\r\n  });\r\n};\r\n```\r\n\r\n### 2. 全员审批 — 验证码校验\r\n\r\n发送短信/邮件验证码前，必须先通过验证码（CAPTCHA）校验。使用 `emitAllApproved` 确保**所有**验证都通过：\r\n\r\n**定义事件** `$events/captcha.event.ts`：\r\n\r\n```ts\r\nexport interface _ {\r\n  'captcha:validate': {\r\n    context: MilkioContext;\r\n    scene: 'login' | 'safety';\r\n    ret: number;\r\n    ticket?: string;\r\n    randstr: string;\r\n  };\r\n}\r\n```\r\n\r\n**触发审批** `user/device/login/2-captcha.action.ts`：\r\n\r\n```ts\r\n// 所有 captcha:validate 的 handler 都必须通过，否则抛出异常\r\nawait context.emitAllApproved('captcha:validate', { context, ...params.captcha });\r\n// 通过后，继续发送验证码...\r\n```\r\n\r\n**处理审批** `captcha/$handlers/captcha.handler.ts`：\r\n\r\n```ts\r\nexport default (world: MilkioWorld<typeof generated>) => {\r\n  world.on('captcha:validate', async (event) => {\r\n    // 调用验证码服务校验\r\n    const result = await client.DescribeCaptchaResult({ ... });\r\n    // 验证失败直接抛异常，阻止整个流程\r\n    if (result.CaptchaCode !== 1 || (result.EvilLevel ?? 0) >= 80) {\r\n      throw event.context.fail('CAPTCHA_INVALID', undefined);\r\n    }\r\n    return true;  // 验证通过\r\n  });\r\n};\r\n```\r\n\r\n### 3. 任意审批 — 下载鉴权\r\n\r\n文件下载鉴权时，多个模块可能都有权放行（不限速下载、抢先体验等），只要有一个模块同意即可：\r\n\r\n**定义事件** `$events/akira-storage.event.ts`：\r\n\r\n```ts\r\nexport interface _ {\r\n  'sync:akira-storage:download-validate': {\r\n    url: string;\r\n    timestamp: number;\r\n    usageType: string;\r\n    data: Record<string, any>;\r\n    context: MilkioContext;\r\n    db: MilkioContext['db'];\r\n  };\r\n}\r\n```\r\n\r\n**触发审批** `sync/akira-storage/eo-download-remote-auth.action.ts`：\r\n\r\n```ts\r\nconst allow = await context.emitAnyApproved('sync:akira-storage:download-validate', emitData);\r\nif (!allow) {\r\n  context.logger.error('鉴权未被通过', emitData);\r\n  throw context.fail('REQUEST_FAIL', undefined);\r\n}\r\n```\r\n\r\n**处理审批** `subscription/$handlers/handle-storage-download-validate.handler.ts`：\r\n\r\n```ts\r\nexport default (world: MilkioWorld<typeof generated>) => {\r\n  world.on('sync:akira-storage:download-validate', async ({ data }) => {\r\n    // 订阅模块允许下载\r\n    data.allow = true;\r\n  });\r\n};\r\n```\r\n\r\n### 4. 手动审批 — 支付校验\r\n\r\n支付创建时使用普通 `emit` + 手动检查 `data.allow` 的模式。这种模式允许在事件触发过程中修改数据，触发方在事件返回后再做判断：\r\n\r\n**触发并检查** `payment/add.action.ts`：\r\n\r\n```ts\r\nconst emitData = {\r\n  data: { ...paymentData, allow: false },  // allow 初始为 false\r\n  fromModule: params.fromModule,\r\n  context,\r\n  tx: context.db,\r\n};\r\n\r\nawait context.emit('payment:validate', emitData);\r\n\r\n// 事件处理完成后，检查是否有模块审批通过\r\nif (!emitData.data.allow) {\r\n  throw context.fail('PAYMENT_ADD_FAILED', undefined);\r\n}\r\n// 审批通过，继续创建支付订单...\r\n```\r\n\r\n**处理审批** `product/$handlers/handle-payment.handler.ts`：\r\n\r\n```ts\r\nworld.on('payment:validate', async ({ data, tx, context, fromModule }) => {\r\n  if (fromModule !== 'product') return;\r\n\r\n  // 校验金额、币种等...\r\n  if (!validatePaymentData(data)) throw context.fail('PAYMENT_ADD_FAILED', undefined);\r\n\r\n  // 审批通过\r\n  data.allow = true;\r\n});\r\n```\r\n\r\n> 这种模式与 `emitAllApproved` 的区别在于：handler 通过修改 `data.allow` 而非返回值来审批，触发方在 `emit` 返回后自行检查。这适用于需要在同一个 `data` 对象上传递更多信息的场景。\r\n\r\n### 5. 级联事件 — 用户删除触发空间删除\r\n\r\n用户删除后，需要级联清理空间、存储、同步文档等。通过 `user:remove` → `space:delete` 的事件链实现：\r\n\r\n```ts\r\n// /app/modules/user/task-auto-remove.action.ts\r\nawait context.emit('user:remove', { data: user, context, db: context.db });\r\n\r\n// /app/modules/space/$handlers/cleanup-user-spaces.handler.ts\r\nworld.on('user:remove', async ({ data, context, db }) => {\r\n  // 标记用户的空间为删除\r\n  await db.update(spaceTable).set({ deletedAt: new Date() }).where(...);\r\n  // 触发空间删除事件\r\n  await context.emit('space:delete', { data: space, context, db });\r\n});\r\n\r\n// /app/modules/storage/$handlers/clear-storage.handler.ts\r\nworld.on('space:delete', async ({ data, db, context }) => {\r\n  // 清理空间下的存储文件\r\n  await db.delete(storageTable).where(eq(storageTable.spaceId, data.id));\r\n});\r\n\r\n// /app/modules/sync-document/$handlers/clear-sync-document.handler.ts\r\nworld.on('space:delete', async ({ data, db, context }) => {\r\n  // 清理空间下的同步文档\r\n  await db.delete(syncDocumentTable).where(eq(syncDocumentTable.spaceId, data.id));\r\n});\r\n```\r\n\r\n---\r\n\r\n## 事件数据中的公共字段\r\n\r\n在项目实践中，事件数据通常包含以下公共字段，以便 handler 获取上下文：\r\n\r\n| 字段 | 类型 | 说明 |\r\n|------|------|------|\r\n| `context` | `MilkioContext` | 当前请求上下文，包含用户信息、配置、日志等 |\r\n| `db` | `MilkioContext['db']` | 数据库实例（非事务） |\r\n| `tx` | `MilkioContext['db']` | 事务实例（如果触发方在事务中） |\r\n| `data` | 各种类型 | 事件的核心数据 |\r\n| `fromModule` | `string` | 触发来源模块标识，用于 handler 过滤 |\r\n\r\n---\r\n\r\n## 测试事件\r\n\r\n通过 astra，你可以直接使用 `world.emit()` 来触发事件。这赋予了你在运行测试时，直接测试事件的能力。测试代码需要写入到 `__TEST__.test.ts` 文件中。\r\n\r\n### 基本用法\r\n\r\n```ts\r\nconst [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\nconst [error, result, meta] = await world.emit(\"event:notify\", {\r\n  params: { message: 'hello', received: [] },\r\n});\r\n\r\nif (error) throw fail(\"事件触发失败\", error);\r\n// result 是 handler 修改后的事件数据\r\nexpect(result.received).toContain('handler-a');\r\nexpect(meta.executeId).toBeDefined();\r\n```\r\n\r\n### 验证 handler 副作用\r\n\r\n事件数据通过引用传递，handler 的修改反映在 `result` 中：\r\n\r\n```ts\r\nconst [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\nconst [error, result] = await world.emit(\"event:notify\", {\r\n  params: { message: 'hello', received: [] },\r\n});\r\nif (error) throw fail(\"事件触发失败\", error);\r\n// handler 内部 push 了 'handler-a'，返回的 result.received 包含该项\r\nexpect(result.received).toEqual(['handler-a']);\r\n```\r\n\r\n### 测试 handler 异常\r\n\r\n```ts\r\nconst [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\nconst [error, result] = await world.emit(\"event:fail\", {\r\n  params: { message: 'boom' },\r\n});\r\nexpect(error).toHaveProperty(\"INTERNAL_SERVER_ERROR\");\r\nexpect(result).toBeNull();\r\n```\r\n\r\n---\r\n\r\n## 最佳实践\r\n\r\n1. **审批事件必须检查 `fromModule`**：handler 应先判断 `fromModule` 是否是自己关心的模块，避免误处理其他模块的事件。\r\n2. **`emitAllApproved` 用于安全关键路径**：如验证码校验、支付校验等，确保所有校验都通过才继续。\r\n3. **`emitAnyApproved` 用于多源授权**：如下载鉴权，多个模块可能都有权放行。\r\n4. **审批通过时显式设置 `data.allow = true`**：不要依赖隐式逻辑，`allow` 默认为 `false`，handler 必须显式同意。\r\n5. **审批失败时抛异常而非返回 false**：`emitAllApproved` 的 handler 如果校验失败，应 `throw context.fail(...)` 抛出异常，而非默默返回 `false`。\r\n6. **非 `app:` 前缀的事件不会推送前端**：服务端内部事件不要使用 `app:` 前缀，避免不必要的推流。\r\n7. **事件数据传引用**：事件数据对象是引用传递，handler 可以修改 `data.allow` 等字段，触发方可以在 `emit` 返回后读取修改后的值。\r\n8. **事务中使用 `tx` 而非 `db`**：如果触发方在事务中，事件数据应传递 `tx`，让 handler 的操作也在同一事务中。\r\n",
    "docs/point-server.md": "# Point\r\n\r\n## 示例\r\n\r\n如前文所述，一个模块通常包含五个端点，合称 BREAD：`browse.action.ts`（浏览列表）、`read.action.ts`（读取单条）、`edit.action.ts`（编辑）、`add.action.ts`（添加）、`delete.action.ts`（删除）。以下是各端点的示例。\r\n\r\n`add.action.ts` 的示例：\r\n\r\n```\r\n// /app/modules/application/add.action.ts\r\nimport { MilkioContext, MilkioMeta } from '../../../.milkio/declares.ts';\r\nimport { articleTable, type ArticleInsert } from \"./$databases/article.table.ts\";\r\nimport { createId } from \"../../utils/create-id.ts\";\r\n\r\nexport const meta: MilkioMeta = {\r\n  allow: [],\r\n};\r\n\r\ntype Params = {\r\n  data: ArticleInsert;\r\n}\r\n\r\ntype Result = {\r\n  id: string;\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  context.logger.info('端点请求参数 (add.action.ts)', JSON.stringify(params));\r\n\r\n  const id = createId();\r\n  const data = {\r\n    ...params.data,\r\n    id,\r\n  } satisfies typeof articleTable.$inferInsert;\r\n\r\n  await context.db.insert(articleTable).values(data);\r\n\r\n  const result = { id };\r\n  context.logger.info('端点请求结果 (add.action.ts)', JSON.stringify(result));\r\n  \r\n  return result;\r\n};\r\n```\r\n\r\n`browse.action.ts` 的示例：\r\n\r\n```\r\n// /app/modules/application/browse.action.ts\r\nimport { MilkioContext, MilkioMeta } from '../../../.milkio/declares.ts';\r\nimport type typia from \"typia\";\r\nimport { and, asc, gt, type SQL } from \"drizzle-orm\";\r\nimport { articleTable, type Article } from \"./$databases/article.table.ts\";\r\n\r\nexport const meta: MilkioMeta = {\r\n  allow: [],\r\n};\r\n\r\ntype Params = {\r\n  limit?: number & typia.tags.Maximum<128>;\r\n  cursor?: string;\r\n}\r\n\r\ntype Result = {\r\n  data: Article[];\r\n  cursor: string | undefined;\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  context.logger.info('端点请求参数 (browse.action.ts)', JSON.stringify(params));\r\n\r\n  const whereCase: Array<SQL> = [];\r\n  if (params.cursor) whereCase.push(gt(articleTable.id, params.cursor));\r\n\r\n  const data = await context.db.query.articleTable.findMany({\r\n    where: and(...whereCase),\r\n    limit: params.limit ?? 128,\r\n    orderBy: [asc(articleTable.id)],\r\n  });\r\n\r\n  const cursor = data.at(-1)?.id;\r\n\r\n  const result = {\r\n    data,\r\n    cursor,\r\n  };\r\n  context.logger.info('端点请求结果 (browse.action.ts)', JSON.stringify(result));\r\n\r\n  return result;\r\n};\r\n```\r\n\r\n注意：默认使用游标分页，如示例所示。**仅当用户明确需要时，才改用 offset 分页。**\r\n\r\n`delete.action.ts` 的示例：\r\n\r\n```\r\n// /app/modules/application/delete.action.ts\r\nimport { MilkioContext, MilkioMeta } from '../../../.milkio/declares.ts';\r\nimport { and, eq, inArray, type SQL } from \"drizzle-orm\";\r\nimport { articleTable } from \"./$databases/article.table.ts\";\r\n\r\nexport const meta: MilkioMeta = {\r\n  allow: [],\r\n};\r\n\r\ntype Params = {\r\n  id: string | Array<string>;\r\n}\r\n\r\ntype Result = {\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  context.logger.info('端点请求参数 (delete.action.ts)', JSON.stringify(params));\r\n\r\n  const whereCase: Array<SQL> = [];\r\n  if (!Array.isArray(params.id)) whereCase.push(eq(articleTable.id, params.id));\r\n  if (Array.isArray(params.id)) whereCase.push(inArray(articleTable.id, params.id));\r\n\r\n  await context.db.delete(articleTable).where(and(...whereCase));\r\n\r\n  return {};\r\n};\r\n```\r\n\r\n`edit.action.ts` 的示例：\r\n\r\n注意，更新时采用了乐观锁机制，防止并发更新导致数据覆盖。\r\n\r\n原理：将读取时的 `updatedAt` 作为更新条件，若期间有其他请求修改了该行，`updatedAt` 已变化，更新影响 0 行即检测到冲突。\r\n\r\n```\r\n// /app/modules/application/edit.action.ts\r\nimport { MilkioContext, MilkioMeta } from '../../../.milkio/declares.ts';\r\nimport { and, eq, type SQL } from \"drizzle-orm\";\r\nimport { articleTable, type Article } from \"./$databases/article.table.ts\";\r\n\r\nexport const meta: MilkioMeta = {\r\n  allow: [],\r\n};\r\n\r\ntype Params = {\r\n  data: Article;\r\n}\r\n\r\ntype Result = {\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  context.logger.info('端点请求参数 (edit.action.ts)', JSON.stringify(params));\r\n\r\n  const whereCase: Array<SQL> = [];\r\n  whereCase.push(eq(articleTable.id, params.data.id));\r\n  whereCase.push(eq(articleTable.updatedAt, params.data.updatedAt));\r\n\r\n  const result = await context.db.update(articleTable).set({ ...params.data, updatedAt: undefined }).where(and(...whereCase)).limit(1);\r\n  if (result[0].affectedRows === 0) throw context.fail(\"DATA_CONFLICT\", undefined);\r\n\r\n  return {};\r\n};\r\n```\r\n\r\n`read.action.ts` 的示例：\r\n\r\n```\r\n// /app/modules/application/read.action.ts\r\nimport { MilkioContext, MilkioMeta } from '../../../.milkio/declares.ts';\r\nimport { and, eq, type SQL } from \"drizzle-orm\";\r\nimport { articleTable, type Article } from \"./$databases/article.table.ts\";\r\n\r\nexport const meta: MilkioMeta = {\r\n  allow: [],\r\n};\r\n\r\ntype Params = {\r\n  id: string;\r\n}\r\n\r\ntype Result = {\r\n  data: Article;\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  context.logger.info('端点请求参数 (read.action.ts)', JSON.stringify(params));\r\n\r\n  const whereCase: Array<SQL> = [];\r\n  if (params.id) whereCase.push(eq(articleTable.id, params.id));\r\n  if (whereCase.length === 0) {\r\n    context.logger.error('缺少查询条件 (read.action.ts)', JSON.stringify(params));\r\n    throw context.fail(\"DATA_NOT_FOUND\", undefined);\r\n  }\r\n\r\n  const data = await context.db.query.articleTable.findFirst({\r\n    where: and(...whereCase),\r\n  });\r\n  if (!data) {\r\n    context.logger.error('数据不存在 (read.action.ts)', JSON.stringify(params));\r\n    throw context.fail(\"DATA_NOT_FOUND\", undefined);\r\n  }\r\n\r\n  const result = {\r\n    data,\r\n  };\r\n  context.logger.info('端点请求结果 (read.action.ts)', JSON.stringify(result));\r\n\r\n  return result;\r\n};\r\n```\r\n\r\n`read-many.action.ts` 的示例：\r\n\r\n```\r\n// /app/modules/application/read-many.action.ts\r\nimport { MilkioContext, MilkioMeta } from '../../../.milkio/declares.ts';\r\nimport { and, inArray, type SQL } from \"drizzle-orm\";\r\nimport { articleTable, type Article } from \"./$databases/article.table.ts\";\r\n\r\nexport const meta: MilkioMeta = {\r\n  allow: [],\r\n};\r\n\r\ntype Params = {\r\n  ids: Array<string>;\r\n}\r\n\r\ntype Result = {\r\n  data: Article[];\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  context.logger.info('端点请求参数 (read-many.action.ts)', JSON.stringify(params));\r\n\r\n  const whereCase: Array<SQL> = [];\r\n  if (params.ids) whereCase.push(inArray(articleTable.id, params.ids));\r\n\r\n  const data = await context.db.query.articleTable.findMany({\r\n    where: and(...whereCase),\r\n  });\r\n\r\n  const result = {\r\n    data,\r\n  };\r\n  context.logger.info('端点请求结果 (read-many.action.ts)', JSON.stringify(result));\r\n\r\n  return result;\r\n};\r\n```\r\n\r\n## 内部动作（$exports）\r\n\r\n有些动作不需要对外暴露为 HTTP 接口，仅供模块内部或其他模块调用，这类动作放在 `$exports` 目录下。**`$exports` 目录中的动作不会注册为端点。**\r\n\r\n例如，更新用户点数的动作不应由前端直接调用，而应由支付模块等其他模块内部调用：\r\n\r\n```\r\n// /app/modules/points/$exports/add.action.ts\r\nimport { MilkioContext, MilkioMeta } from '../../../../.milkio/declares.ts';\r\nimport { pointsTable, type PointsInsert } from \"./$databases/points.table.ts\";\r\nimport { createId } from \"../../utils/create-id.ts\";\r\n\r\nexport const meta: MilkioMeta = {\r\n  allow: [],\r\n};\r\n\r\ntype Params = {\r\n  data: {\r\n    userId: string;\r\n    points: number;\r\n  };\r\n}\r\n\r\ntype Result = {\r\n  points: number;\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n    context.logger.info('端点请求参数 ($exports/add.action.ts)', JSON.stringify(params));\r\n\r\n    // 操作用户的点数...\r\n    const result = {\r\n        points: params.data.points,\r\n    };\r\n    context.logger.info('端点请求结果 ($exports/add.action.ts)', JSON.stringify(result));\r\n    \r\n    return result;\r\n};\r\n```\r\n\r\n在其他动作中，可通过 `context.call` 调用内部动作：\r\n\r\n```ts\r\nconst result = await context.call(import('../points/$exports/add.action.ts'), {\r\n  data: {\r\n    userId: params.data.userId,\r\n    points: 100,\r\n  },\r\n});\r\nconsole.log(result.points); // 100\r\n```\r\n\r\n## Params 与 Result 的类型\r\n\r\nParams 与 Result 的类型应尽量基于数据库表类型派生，**避免直接使用 `number`、`string` 等基础类型**。可以通过 `Omit` 排除不需要的字段：\r\n\r\n```ts\r\nimport { User } from \"../../users/$databases/users.table.ts\";\r\n\r\ntype Params = Omit<User, 'uploadAt' | 'clientId' | 'clientIp'>;\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n) {\r\n    // ...\r\n};\r\n```\r\n\r\n也可以只选取需要的字段：\r\n\r\n```ts\r\nimport { User } from \"../../users/$databases/users.table.ts\";\r\n\r\ntype Params = {\r\n  id: User['id'];\r\n  username: User['username'];\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n) {\r\n    // ...\r\n};\r\n```\r\n\r\n对于分页、排序等数据库中无对应字段的参数的场景，才可直接使用基础类型。\r\n\r\n类型定义很重要——Milkio 基于 typia 会根据你定义的类型对前端传参进行校验：被 `Omit` 排除的字段会被自动过滤；缺少必填字段则会直接返回失败响应。\r\n\r\n不要解构参数，避免 `const { userId, points } = params.data` 这种写法，应直接使用 `params.data.userId`、`params.data.points` 访问。\r\n\r\n尽量避免可选属性。代码都是你写的，你自然知道一个参数到底应该传还是不应该传。如果前端在发送请求的时候都传了，那你就不要假定这个参数是可以不传的。这更接近 Golang 的设计哲学，Golang 是没有可选参数的，如果一个值是可空的，而且确实有必要留空，那么可以先在注释里解释清楚什么情况下可以留空，然后使用联合类型，如 `id: User['id'] | null` 或者 `id: User['id'] | undefined`。\r\n\r\n## 错误处理\r\n\r\n失败分为两类，**定义在同一个 `*.code.ts` 里**：\r\n\r\n- **`Fail`（fail-code）**：预期内的业务拒绝，日志 warn 级，**不采集堆栈**，`code` 与 `data` 返回给客户端；\r\n- **`Fault`（fault-code）**：意料外/内部错误，日志 error 级，带堆栈与 cause，**仅本工程内部使用**，客户端只会收到通用 `\"INTERNAL_SERVER_ERROR\"`。\r\n\r\n系统公共错误码定义在 `/app/codes` 目录下，模块专属错误码定义在 `/app/modules/模块名/$codes/模块名.code.ts` 中。每个文件必须同时导出 `Fail` 与 `Fault`（可以为空）：\r\n\r\n```\r\n// /app/modules/point/$codes/point.code.ts\r\nexport interface Fail {\r\n  /**\r\n   * 点数兑换失败\r\n   */\r\n  POINT_EXCHANGE_FAILED: undefined;\r\n  /**\r\n   * 点数不足\r\n   */\r\n  POINT_INSUFFICIENT: {\r\n    required: number;\r\n    available: number;\r\n  };\r\n}\r\n\r\nexport interface Fault {\r\n  /**\r\n   * 账本不变量被破坏，属于程序异常，不应发生\r\n   */\r\n  POINT_LEDGER_INVARIANT_BROKEN: {\r\n    ledgerId: string;\r\n  };\r\n}\r\n```\r\n\r\n抛出示例：\r\n\r\n```ts\r\n// fail：业务拒绝，warn，无堆栈，data 发给客户端\r\nthrow context.fail(\"POINT_EXCHANGE_FAILED\", undefined);\r\nthrow context.fail(\"POINT_INSUFFICIENT\", {\r\n  required: 100,\r\n  available: 50,\r\n});\r\n\r\n// fault：内部异常，error，带堆栈，只进服务端日志\r\nthrow context.fault(\"POINT_LEDGER_INVARIANT_BROKEN\", { ledgerId });\r\n```\r\n\r\n**重点：fail-code 的数据结构中不得包含 `message` 等文本字段。** 具体的错误提示文案应由前端根据错误码生成——后端返回文本会导致国际化困难，且增加传输体积。前端根据错误码决定展示内容；对于携带数据的错误码，前端可利用这些数据拼装出完整的提示信息。\r\n\r\n**fault-code 的 data 可以包含内部细节**（SQL、上游响应等），它不会返回给客户端，只用于日志和 `onError`。不要把 `catch` 到的未意料异常包装成 `context.fail`，直接 `throw` 或 `context.fault` 才会按 error 级记录。\r\n\r\n## 测试\r\n\r\n前文提到，你应该在对应模块的目录下创建一个 `__TEST__.test.ts`，在里面存放该模块所有相关的测试代码，并且在每次编写完成代码之后，运行一遍相关的测试。\r\n\r\n### 测试用例示例\r\n\r\n以下示例展示了针对不同动作（增、删、改、查、批量查）的标准测试写法：\r\n\r\n**基础创建与查询测试 (`add`, `read`)**：\r\n```ts\r\nimport { expect, test } from \"vite-plus/test\";\r\nimport { astra } from \"../../utils/test.ts\";\r\n\r\n/**\r\n * 调试测试：快速执行创建动作\r\n * 目的：在开发过程中快速验证接口是否可正常调用，\r\n * 不做断言，仅用于调试和观察返回值。\r\n */\r\ntest(\"adjust\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 调试：执行创建动作，generateParams 会自动生成符合接口定义的随机参数\r\n  await world.execute(\"/application/add\", { generateParams: true });\r\n});\r\n\r\n/**\r\n * 基础创建与查询测试\r\n * 验证数据的创建和查询流程：\r\n * 1. 调用 add 接口创建一条新数据\r\n * 2. 使用返回的 ID 调用 read 接口查询该数据\r\n * 3. 断言查询结果中的 ID 与创建时返回的 ID 一致\r\n */\r\ntest(\"basic\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 关键：清理数据库，确保测试环境干净，避免其他测试数据的干扰\r\n  await world.cleanDatabase();\r\n\r\n  // 1. 调用创建接口，generateParams 会自动填充所需的参数字段\r\n  const [errorAdd, resultAdd] = await world.execute(\"/application/add\", { generateParams: true });\r\n  if (errorAdd) throw fail(\"创建失败\", errorAdd);\r\n  // 获取新建数据的 ID，用于后续查询\r\n  const newId = resultAdd.id;\r\n\r\n  // 2. 调用查询接口，通过 ID 查询刚创建的数据，验证数据已正确持久化\r\n  const [errorGet, resultGet] = await world.execute(\"/application/read\", { generateParams: false, params: { id: newId } });\r\n  if (errorGet) throw fail(\"查询失败\", errorGet);\r\n\r\n  // 3. 断言：查询结果中的 ID 应与创建时返回的 ID 一致，确认数据完整性\r\n  expect(resultGet.data?.id).toBe(newId);\r\n});\r\n```\r\n\r\n**查询列表测试 (`browse`)**：\r\n```ts\r\nimport { expect, test } from \"vite-plus/test\";\r\nimport { astra } from \"../../utils/test.ts\";\r\n\r\n/**\r\n * 调试测试：快速执行列表查询动作\r\n * 目的：在开发过程中快速验证 browse 接口是否可正常调用，\r\n * 不做断言，仅用于调试和观察返回值。\r\n */\r\ntest(\"adjust\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 调试：执行列表查询动作，generateParams 会自动生成查询参数\r\n  await world.execute(\"/application/browse\", { generateParams: true });\r\n});\r\n\r\n/**\r\n * 查询列表测试\r\n * 验证列表查询接口能正确返回已创建的数据：\r\n * 1. 先创建一条数据\r\n * 2. 调用 browse 接口查询列表\r\n * 3. 断言列表中包含刚创建的数据\r\n */\r\ntest(\"basic\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 关键：清理数据库，确保测试环境干净，避免其他测试数据的干扰\r\n  await world.cleanDatabase();\r\n\r\n  // 创建一条数据，后续用来验证列表查询结果\r\n  const [errorAdd, resultAdd] = await world.execute(\"/application/add\", { generateParams: true });\r\n  if (errorAdd) throw fail(\"Execution failed\", errorAdd);\r\n  // 记录创建数据的 ID，用于后续在列表中查找匹配\r\n  const id = resultAdd.id;\r\n\r\n  // 调用 browse 接口查询数据列表\r\n  const [errorBrowse, resultBrowse] = await world.execute(\"/application/browse\", { generateParams: false });\r\n  if (errorBrowse) throw fail(\"Execution failed\", errorBrowse);\r\n\r\n  // 断言：列表中应能找到刚创建的数据，确认 browse 接口返回完整数据\r\n  const found = resultBrowse.data.find((item) => item.id === id);\r\n  expect(Boolean(found)).toBe(true);\r\n});\r\n```\r\n\r\n**删除测试 (`delete`)**：\r\n```ts\r\nimport { expect, test } from \"vite-plus/test\";\r\nimport { astra } from \"../../utils/test.ts\";\r\n\r\n/**\r\n * 调试测试：快速执行删除动作\r\n * 目的：在开发过程中快速验证 delete 接口是否可正常调用，\r\n * 不做断言，仅用于调试和观察返回值。\r\n */\r\ntest(\"adjust\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 调试：执行删除动作，generateParams 会自动生成包含 ID 的删除参数\r\n  await world.execute(\"/application/delete\", { generateParams: true });\r\n});\r\n\r\n/**\r\n * 删除测试\r\n * 验证删除接口能正确移除数据：\r\n * 1. 先创建一条数据\r\n * 2. 调用 delete 接口删除该数据\r\n * 3. 再次查询该数据，断言应返回 DATA_NOT_FOUND 错误\r\n */\r\ntest(\"basic\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 关键：清理数据库，确保测试环境干净，避免其他测试数据的干扰\r\n  await world.cleanDatabase();\r\n\r\n  // 创建一条数据，后续用来测试删除功能\r\n  const [errorAdd, resultAdd] = await world.execute(\"/application/add\", { generateParams: true });\r\n  if (errorAdd) throw fail(\"创建失败\", errorAdd);\r\n  // 记录创建数据的 ID，用于后续删除和验证\r\n  const id = resultAdd.id;\r\n\r\n  // 调用删除接口，通过 ID 删除刚创建的数据\r\n  const [errorDelete, resultDelete] = await world.execute(\"/application/delete\", { generateParams: false, params: { id } });\r\n  if (errorDelete) throw fail(\"删除失败\", errorDelete);\r\n\r\n  // 再次查询该数据，验证其已被删除\r\n  const [errorGet, resultGet] = await world.execute(\"/application/read\", { generateParams: false, params: { id } });\r\n\r\n  // 关键断言：确保错误类型是 DATA_NOT_FOUND，说明数据已被成功删除\r\n  if (!(errorGet?.kind === \"fail\" && errorGet.code === \"DATA_NOT_FOUND\")) {\r\n    throw fail(\"删除后查询未返回预期错误\", errorGet);\r\n  }\r\n});\r\n```\r\n\r\n**更新测试 (`edit`)**：\r\n```ts\r\nimport { expect, test } from \"vite-plus/test\";\r\nimport { astra } from \"../../utils/test.ts\";\r\n\r\n/**\r\n * 调试测试：快速执行更新动作\r\n * 目的：在开发过程中快速验证 edit 接口是否可正常调用，\r\n * 不做断言，仅用于调试和观察返回值。\r\n */\r\ntest(\"adjust\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 调试：执行更新动作，generateParams 会自动生成更新所需的参数\r\n  await world.execute(\"/application/edit\", { generateParams: true });\r\n});\r\n\r\n/**\r\n * 更新测试\r\n * 验证更新接口能正确修改数据：\r\n * 1. 先创建一条数据\r\n * 2. 查询并记录更新前的数据快照\r\n * 3. 调用 edit 接口更新该数据\r\n * 4. 查询更新后的数据\r\n * 5. 断言更新前后的数据不一致，确认更新生效\r\n */\r\ntest(\"basic\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 关键：清理数据库，确保测试环境干净，避免其他测试数据的干扰\r\n  await world.cleanDatabase();\r\n\r\n  // 创建一条数据，后续用来测试更新功能\r\n  const [errorAdd, resultAdd] = await world.execute(\"/application/add\", { generateParams: true });\r\n  if (errorAdd) throw fail(\"创建失败\", errorAdd);\r\n  // 记录创建数据的 ID，用于后续查询和更新定位\r\n  const id = resultAdd.id;\r\n\r\n  // 记录更新前的数据快照，用于与更新后的数据做对比\r\n  const [errorBefore, resultBefore] = await world.execute(\"/application/read\", { generateParams: false, params: { id } });\r\n  if (errorBefore) throw fail(\"查询失败（更新前）\", errorBefore);\r\n\r\n  // 执行更新动作：params 中的 id 用于定位要更新的数据，generateParams 会生成其他更新字段\r\n  const [errorUpdate, resultUpdate] = await world.execute(\"/application/edit\", {\r\n    params: { data: { id } },\r\n    generateParams: true,\r\n  });\r\n  if (errorUpdate) throw fail(\"更新失败\", errorUpdate);\r\n\r\n  // 获取更新后的数据，用于与更新前做对比\r\n  const [errorAfter, resultAfter] = await world.execute(\"/application/read\", { generateParams: false, params: { id } });\r\n  if (errorAfter) throw fail(\"查询失败（更新后）\", errorAfter);\r\n\r\n  // 断言：更新前后的数据不应完全相同，确认更新操作确实修改了数据\r\n  expect(resultBefore.data).not.toEqual(resultAfter.data);\r\n});\r\n```\r\n\r\n**批量查询测试 (`read-many`)**：\r\n```ts\r\nimport { expect, test } from \"vite-plus/test\";\r\nimport { astra } from \"../../utils/test.ts\";\r\n\r\n/**\r\n * 调试测试：快速执行批量查询动作\r\n * 目的：在开发过程中快速验证 read-many 接口是否可正常调用，\r\n * 不做断言，仅用于调试和观察返回值。\r\n */\r\ntest(\"adjust\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 调试：执行单条查询动作（注意这里用 read 做快速调试）\r\n  await world.execute(\"/application/read\", { generateParams: true });\r\n});\r\n\r\n/**\r\n * 批量查询测试\r\n * 验证 read-many 接口能正确批量返回多条数据：\r\n * 1. 批量创建随机数量的数据，记录所有 ID\r\n * 2. 调用 read-many 接口，传入所有 ID\r\n * 3. 断言返回的数据条数与创建的条数一致\r\n */\r\ntest(\"basic\", async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 关键：清理数据库，确保测试环境干净，避免其他测试数据的干扰\r\n  await world.cleanDatabase();\r\n\r\n  // 批量创建随机数量的数据（0~32 条），模拟真实的批量场景\r\n  const count = Math.floor(Math.random() * 33);\r\n  // 收集所有创建数据的 ID，用于后续批量查询\r\n  const ids: Array<string> = [];\r\n\r\n  for (let i = 0; i < count; i++) {\r\n    const [errorAdd, resultAdd] = await world.execute(\"/application/add\", { generateParams: true });\r\n    if (errorAdd) throw fail(\"创建失败\", errorAdd);\r\n    // 将每条新建数据的 ID 添加到数组中\r\n    ids.push(resultAdd.id);\r\n  }\r\n\r\n  // 执行批量查询，传入所有创建数据的 ID 列表\r\n  const [errorReadMany, resultReadMany] = await world.execute(\"/application/read-many\", { generateParams: false, params: { ids } });\r\n  if (errorReadMany) throw fail(\"批量查询失败\", errorReadMany);\r\n\r\n  // 断言：返回的数据条数应与创建的条数一致，确认批量查询返回了完整的结果\r\n  expect(resultReadMany.data.length).toEqual(count);\r\n});\r\n```\r\n\r\n### 测试用例注释\r\n\r\n编写的测试需要包含详尽的中文注释，确保可读性。包括在测试开头添加多行注释，描述测试的意图，以及在测试的实际代码中，描述每一个步骤的作用。下面是一个实际的例子：\r\n\r\n```ts\r\n/**\r\n * 无效时间精度测试\r\n * 验证 effectiveAt 必须是 UTC 0 点整：\r\n * 1. 传入包含时分秒的时间（非 UTC 0 点）\r\n * 2. 应返回 INVALID_TIME_PRECISION 错误\r\n */\r\ntest('invalidTimePrecision', async () => {\r\n  const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  await world.cleanDatabase();\r\n\r\n  const invalidDate = new Date('2025-01-15T10:30:00Z');\r\n\r\n  // 调用点数模块的动作，来添加用户的点数\r\n  const [errorAdd, resultAdd] = await world.execute('/point/$exports/add', {\r\n    generateParams: false,\r\n    params: {\r\n      userId: userSeed.id,\r\n      points: 100,\r\n      effectiveAt: invalidDate,\r\n      days: 30,\r\n      type: 'gift',\r\n    },\r\n  });\r\n\r\n  // 断言：返回的 fail-code 应该是 INVALID_TIME_PRECISION\r\n  if (!errorAdd || errorAdd.kind !== \"fail\" || errorAdd.code !== \"INVALID_TIME_PRECISION\") {\r\n    throw fail('应该返回 INVALID_TIME_PRECISION 错误', errorAdd);\r\n  }\r\n});\r\n```\r\n\r\n### 测试策略建议\r\n*   **成功路径测试**：如以上示例，验证动作在正常情况下的行为是否符合预期。\r\n*   **失败路径测试**：**至关重要**。应编写测试来验证代码在边界条件、异常输入或非法操作下的处理逻辑是否正确（例如，传递非法ID、重复创建、权限不足等）。\r\n*   **测试工具**：我们使用 **Vitest** 作为测试运行器。\r\n\r\n## 错误处理规范\r\n\r\n在动作代码中，使用 `throw context.fail(\"ERROR_CODE\", undefined);` 抛出业务错误；内部异常使用 `throw context.fault(\"FAULT_CODE\", data);`。\r\n\r\n在测试代码中，请使用以下方式检查错误类型（`kind` + `code` 收窄）：\r\n\r\n```typescript\r\n// 正确：先确认是 fail，再按 code 收窄\r\nif (error?.kind === \"fail\" && error.code === \"VERIFICATION_CODE_INVALID\") {\r\n    // 处理验证码无效的错误\r\n}\r\n\r\nif (!(error?.kind === \"fail\" && error.code === \"VERIFICATION_CODE_INVALID\")) {\r\n    // 处理其他类型的错误\r\n}\r\n```\r\n\r\n**重要**：不要使用 keyed-map 写法（`\"CODE\" in error` / `error.CODE`），也不要用 `as any` 绕过类型：\r\n\r\n```typescript\r\n// 错误！禁止使用\r\nexpect(error?.code).toBe(\"VERIFICATION_CODE_INVALID\");     // 缺少 kind 收窄\r\nexpect(error?.VERIFICATION_CODE_INVALID).toBeDefined();    // 旧 keyed-map 写法\r\n```\r\n\r\n## 随机参数生成\r\n\r\n编写测试时，你可以随机生成参数。当 `generateParams`: 设为 `true` 时，系统会自动生成所需参数。\r\n\r\n```ts\r\n// 示例：创建一个随机用户\r\nconst [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\nconst [errorAdd, resultAdd] = await world.execute(\"/user/add\", { generateParams: true });\r\nif (errorAdd) throw fail(\"创建用户失败\", errorAdd);\r\nconst userId = resultAdd.id;\r\n```\r\n\r\n当然，如果你指定了一些参数，那么这些参数将不会随机生成。\r\n\r\n```ts\r\n// 示例：创建一个随机用户，指定用户名\r\nconst [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\nconst [errorAdd, resultAdd] = await world.execute(\"/user/add\", { generateParams: true, params: { data: { username: \"test-user\" } } });\r\nif (errorAdd) throw fail(\"创建用户失败\", errorAdd);\r\nconst userId = resultAdd.id;\r\n```\r\n\r\n注意，这个自动生成数据的规则是\"浅层\"的，只针对 params 中的浅层参数有效，不会尝试递归生成深层的随机参数。\r\n\r\n### generateParams 的取值\r\n\r\n**`generateParams` 是必填字段**，每次调用 `world.execute` 都必须显式指定，不能省略：\r\n\r\n- **`generateParams: true`**：自动生成符合接口类型定义的随机参数。适用于 `adjust` 调试测试，或当参数全部可以随机生成的场景。如果同时提供了 `params`，则 `params` 中指定的字段使用你的值，其余字段自动生成。\r\n- **`generateParams: false`**：不自动生成参数，仅使用你提供的 `params`。**当你手动指定了 `params` 时必须设为 `false`**，否则 TypeScript 会报类型错误——因为 `generateParams: true` 的分支要求参数类型为可选，与手动传入的完整参数类型不兼容。\r\n\r\n```ts\r\n// 错误：有 params 但缺少 generateParams，会报类型错误\r\nawait world.execute(\"/application/read\", { params: { id: newId } });\r\n\r\n// 正确：手动指定参数时设为 false\r\nawait world.execute(\"/application/read\", { generateParams: false, params: { id: newId } });\r\n\r\n// 正确：不需要参数时也设为 false\r\nawait world.execute(\"/application/browse\", { generateParams: false });\r\n\r\n// 正确：调试时用 true 自动生成\r\nawait world.execute(\"/application/add\", { generateParams: true });\r\n```\r\n\r\n### result 类型与非空断言\r\n\r\n`world.execute` 返回的 `result` 中，某些属性的类型可能为 `null` 或 `undefined`（如 `result.data`、`result.voice` 等）。TypeScript 不会从 `expect(...).not.toBeNull()` 中推断类型窄化，因此在断言后访问这些属性仍需使用非空断言 `!`：\r\n\r\n```ts\r\n// 错误：result.data 可能为 undefined，TS 报错\r\nconst id = resultAdd.data.id;\r\n\r\n// 正确：使用 ! 非空断言\r\nconst id = resultAdd.data!.id;\r\n\r\n// 或者在 expect 断言之后\r\nexpect(resultInit.voice).not.toBeNull();\r\nexpect(resultInit.voice!.volume).toBe(50);\r\n```\r\n\r\n## 填充默认数据\r\n\r\n在测试时，我们可能需要用到一些固定的种子数据，例如用户 ID、设备 ID 等。这些信息不能是随机的，否则和数据库中的数据不一致，可能会导致逻辑无法正常运行。\r\n\r\n每个模块中，都有可能存在 `$seeds` 目录，这里会存储一些会被填充到数据库中的种子数据，例如默认的管理员账号等。下面，是一个使用用户 ID 进行测试的示例：\r\n\r\n```ts\r\nimport { userSeed } from \"../../modules/user/$seeds/user.seed.ts\";\r\n\r\n// 示例：使用默认用户 ID 进行测试\r\nconst [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\nconst [errorAdd, resultAdd] = await world.execute(\"/foo/bar/baz\", { generateParams: false, params: { userId: userSeed.id } });\r\n```\r\n\r\n对于后端服务器工程而言，一些常用的种子数据包括：\r\n\r\n*   默认的用户账号：`/modules/user/$seeds/user.seed.ts` (userSeed)\r\n*   默认的设备：`/modules/user/$seeds/user-device.seed.ts` (userDeviceSeed)\r\n*   默认的用户属性（管理员）：`/modules/user/$seeds/user-property.seed.ts` (userPropertySeed)\r\n*   默认的空间：`/modules/space/$seeds/space.seed.ts` (spaceUserDefaultSeed)",
    "docs/point-store.md": "# Point Store\r\n\r\n当 Milkio 工程用作前端状态管理器（embed）时，你可以通过 Milkio 的事件系统 (Events) 来推送给前端视图层 (vue 组件)，触发前端内容的更新。\r\n\r\n## 具体示例\r\n\r\n首先，我们需要在模块的 `$states` 目录下定义实际的状态，用任何方式定义都可以，甚至，你的状态可以使用普通的 JavaScript 对象来实现。这些文件以 `*.state.ts` 命名。内容你可以自由组织，只需要确保它对外导出了一个可增删改查数据的内容即可，甚至是导出一个普通的 JavaScript 对象。但是，不得在其中编写任何逻辑代码。如果你要导出方法，你只能导出普通的诸如 `get`、`set` 等方法，而不能在里面封装任何业务逻辑，甚至包括数据校验、数据结构重组等方法，也不能在这里编写。\r\n\r\n换句话说，它必须要符合\"贫血模型\"的概念，贫血模型是软件设计中的一种领域模型模式，其核心特征是领域对象（如实体、值对象）仅包含数据属性或者简单的访问方法（getter/setter），而将所有业务逻辑都剥离到外部去处理。相似的代码你必须重复地在端点中编写多次，而不应该“封装”在 state 内。\r\n\r\n### 文件规范\r\n\r\n```\r\napp/modules/example/\r\n├── $states/\r\n│   └── sidebar.state.ts    # 状态定义文件\r\n├── toggle-sidebar.action.ts\r\n└── ...\r\n```\r\n\r\n注意，每个状态文件，都必须显式导出类型和实例。再次强调，状态文件中不得编写任何业务逻辑。\r\n\r\n你可以写这样的代码：\r\n\r\n```ts\r\n// /app/modules/example/$states/panel.state.ts\r\nexport type PanelState = {\r\n  open: boolean;\r\n  activeTab: string;\r\n};\r\n\r\nconst instances = new Map<string, Promise<PanelState>>();\r\n\r\nasync function __createPanelState(): Promise<PanelState> {\r\n  return {\r\n    open: false,\r\n    activeTab: 'foo',\r\n  } satisfies PanelState;\r\n}\r\n\r\nexport function usePanelState(userId: string): Promise<PanelState> {\r\n  if (instances.has(userId)) return instances.get(userId)!;\r\n  const promise = __createPanelState();\r\n  instances.set(userId, promise);\r\n  return promise;\r\n}\r\n```\r\n\r\n通常情况下，你大概率都需要隔离状态，因为，用户可能会退出登录 / 重新登录，尽管属于低频场景，但是不同账号的状态确实是应该不一样的。当你认为状态确实不需要按 id 隔离时，`useXxxState` 无需接受参数，内部使用 `const staticKey = '$'` 作为固定的 key：\r\n\r\n```ts\r\n// /app/modules/example/$states/sidebar.state.ts\r\nexport type SidebarState = {\r\n  open: boolean;\r\n  width: number;\r\n  activeId: string | null;\r\n};\r\n\r\nconst instances = new Map<string, Promise<SidebarState>>();\r\n\r\nasync function __createSidebarState(): Promise<SidebarState> {\r\n  return {\r\n    open: true,\r\n    width: 260,\r\n    activeId: null,\r\n  } satisfies SidebarState;\r\n}\r\n\r\nexport function useSidebarState(): Promise<SidebarState> {\r\n  const staticKey = '$';\r\n  if (instances.has(staticKey)) return instances.get(staticKey)!;\r\n  const promise = __createSidebarState();\r\n  instances.set(staticKey, promise);\r\n  return promise;\r\n}\r\n```\r\n\r\n使用示例：\r\n\r\n在 action 中读写：\r\n\r\n```ts\r\n// /app/modules/example/toggle-sidebar.action.ts\r\nimport { useSidebarState } from \"./$states/sidebar.state.ts\";\r\n\r\nexport async function handler(context: MilkioContext, params: Params) {\r\n  context.logger.info('端点请求参数 (toggle-sidebar.action.ts)', JSON.stringify(params));\r\n\r\n  const sidebarState = await useSidebarState();\r\n  if (params.open !== undefined) sidebarState.open = params.open;\r\n\r\n  // 修改后 emit 到 ipcRefs，通知前端\r\n  await context.emit('app:sidebar', { ...sidebarState });\r\n\r\n  const result = { success: true };\r\n  context.logger.info('端点请求结果 (toggle-sidebar.action.ts)', JSON.stringify(result));\r\n  \r\n  return result;\r\n};\r\n```\r\n\r\n这里只是一个简单的示例，在大多数情况下，使用普通的 JavaScript 对象来存储状态就足够了。如果你需要持久化地保存数据，你可能需要使用 `localforage`、`dexie` 之类的库来实现。谨记这需要是一个贫血模型，不要在状态中编写任何业务逻辑，你应该直接导出这个普通的 JavaScript 对象本身，或者导出一个 `localforage` 的 instance 等。总之，你需要根据你的实际业务需要，来选择最合适的技术栈来存储状态。但是必须遵循贫血模型的概念。\r\n\r\n```ts\r\n// localforage\r\nconst instances = new Map<string, Promise<Localforage>>();\r\n\r\nasync function __createSidebarState(): Promise<Localforage> {\r\n  return localforage.createInstance({ name: \"sidebar\" });\r\n}\r\n\r\nexport function useSidebarState(): Promise<Localforage> {\r\n  const staticKey = '$';\r\n  if (instances.has(staticKey)) return instances.get(staticKey)!;\r\n  const promise = __createSidebarState();\r\n  instances.set(staticKey, promise);\r\n  return promise;\r\n}\r\n```\r\n\r\n---\r\n\r\n## 定义事件\r\n\r\n事件类型定义在 `$events` 目录下，是 `ipcRefs` 的类型来源。构建工具会根据此文件自动校验 `context.emit` 的参数类型。\r\n\r\n### 文件规范\r\n\r\n```\r\napp/modules/tab/\r\n├── $events/\r\n│   └── tab.event.ts\r\n├── $states/\r\n└── ...\r\n```\r\n\r\n每个事件文件导出一个名为 `_` 的 interface：\r\n\r\n```ts\r\n// /app/modules/tab/$events/tab.event.ts\r\nexport interface _ {\r\n  'app:tabs': {\r\n    activeTab?: Tab;\r\n    systemTabs: SystemTabs;\r\n    fixedTabs: Tabs;\r\n    tempTabs: Tabs;\r\n  };\r\n  'app:closed:tab': {\r\n    timestamp: number;\r\n    data: Array<{ component: string; meta: string }>;\r\n  };\r\n}\r\n```\r\n\r\n注意，你必须使用**`app:` 前缀**。推送到前端的事件必须使用此前缀，只有以此前缀开头的才会被同步发送给前端。\r\n\r\n## 前端使用\r\n\r\n在前端，通过 `ipcRefs` 可以获取到以 `app:` 开头的事件的内容，会被转化成一个只读的 `ref`。它是与前端 Vue 组件的响应式状态桥梁。\r\n\r\n```vue\r\n<template>\r\n  <!-- 在模板中直接使用其中的值 -->\r\n  <div v-if=\"ipcRefs['app:user-device'].value?.user\">\r\n    {{ ipcRefs['app:user-device'].value.user.name }}\r\n  </div>\r\n</template>\r\n```\r\n\r\n```vue\r\n<script lang=\"ts\" setup>\r\nconst ipcRefs = await useIpcRefs();\r\n\r\n// watch 监听事件变化\r\nwatch(() => ipcRefs['app:tabs'].value?.activeTab, async (data) => {\r\n  if (!data) return;\r\n  // 处理业务逻辑...\r\n}, { immediate: true, deep: true });\r\n</script>\r\n```\r\n\r\n### 工作原理\r\n\r\n```\r\n调用 context.emit('app:xxx', data) 发送事件\r\n        ↓\r\n事件通过 Worker/SSE 推送到前端\r\n        ↓\r\n框架会自动更新 ipcRefs['app:xxx'].value 的值\r\n        ↓\r\nVue 组件通过 useIpcRefs() 获取响应式 Ref，直接读取或 watch\r\n```\r\n\r\n前端组件通过 `useIpcRefs()` 获取一个 Proxy 对象，键为事件名，值为 `DeepReadonly<Ref<T | undefined>>`。每个键都是一个 Vue 响应式 Ref，可以在模板中直接使用或通过 `watch` 监听变化。\r\n\r\n## 推送事件到前端\r\n\r\n任何 action 执行\"写\"操作后，都应 `emit` 更新 `ipcRefs`，让前端自动响应变化：\r\n\r\n```ts\r\n// /app/modules/tab/navigate-to.action.ts\r\nexport async function handler(context: MilkioContext, params: { component: string; meta?: string }) {\r\n  const tabState = await useTabState(context.user?.userDevice.id);\r\n\r\n  // 执行写操作...\r\n\r\n  // emit 完整的最新状态到 ipcRefs\r\n  await context.emit('app:tabs', { ... });\r\n}\r\n```\r\n\r\n## 为 ipcRefs 赋予初始值\r\n\r\n我们可能需要在启动时推送初始数据，让前端组件能立即拿到正确的状态。你可以通过 `$handlers` 监听 `life-cycle:mounted` 生命周期事件来实现。只有所有的 `life-cycle:mounted` 执行完成 (会被 await)，应用程序才会正常执行。\r\n\r\n```ts\r\n// /app/modules/tab/$handlers/tab.handler.ts\r\nexport default (world: MilkioWorld<typeof generated>) => {\r\n  world.on('life-cycle:mounted', async (context) => {\r\n    // 初始化标签页数据\r\n    await context.emit('app:tabs', {\r\n        // ...\r\n    });\r\n  });\r\n};\r\n```\r\n\r\n## 事件推送的过滤逻辑\r\n\r\n`watch.stream.ts` 是前端订阅的流端点，它监听所有事件，但只将 `app:` 前缀的事件推送到前端：\r\n\r\n```ts\r\n// /app/modules/event/watch.stream.ts\r\nexport async function* handler(context: MilkioContext, params: {}) {\r\n  const flow = createFlow<{ key: string; data: any }>();\r\n\r\n  context._.on('*', ({ key, value }) => {\r\n    if (!key.startsWith('app:')) return;  // 仅推送 app: 前缀的事件\r\n    flow.emit({ key, data: value });\r\n  });\r\n\r\n  for await (const chunk of flow) yield chunk;\r\n}\r\n```\r\n\r\n## 完整示例\r\n\r\n### 1. 事件定义\r\n\r\n```ts\r\n// /app/modules/tab/$events/tab.event.ts\r\nimport type { SystemTabs, Tab, Tabs } from '../$states/tab.state';\r\n\r\nexport interface _ {\r\n  'app:tabs': {\r\n    activeTab?: Tab;\r\n    systemTabs: SystemTabs;\r\n    fixedTabs: Tabs;\r\n    tempTabs: Tabs;\r\n  };\r\n  'app:closed:tab': {\r\n    timestamp: number;\r\n    data: Array<{ component: string; meta: string }>;\r\n  };\r\n}\r\n```\r\n\r\n### 2. 赋予 ipcRefs 初始值\r\n\r\n```ts\r\n// /app/modules/tab/$handlers/tab.handler.ts\r\nexport default (world: MilkioWorld<typeof generated>) => {\r\n  world.on('life-cycle:mounted', async (context) => {\r\n    const tabState = await useTabState(context.user?.userDevice.id);\r\n    await context.emit('app:tabs', { ... });\r\n  });\r\n};\r\n```\r\n\r\n### 3. Action 执行写操作并更新 ipcRefs\r\n\r\n```ts\r\n// /app/modules/tab/navigate-to.action.ts\r\nexport async function handler(context: MilkioContext, params: { component: string; meta?: string }) {\r\n  context.logger.info('端点请求参数 (navigate-to.action.ts)', JSON.stringify(params));\r\n\r\n  const tabState = await useTabState(context.user?.userDevice.id);\r\n  \r\n  // 写入数据..\r\n  \r\n  // 写入完成，发送给前端更新后的状态数据\r\n  await context.emit('app:tabs', { ... });\r\n}\r\n```\r\n\r\n### 4. 前端通过 ipcRefs 读取和监听\r\n\r\n```vue\r\n<script lang=\"ts\" setup>\r\nconst ipcRefs = await useIpcRefs();\r\n\r\nwatch(() => ipcRefs['app:tabs'].value?.activeTab, async (activeTab) => {\r\n  if (!activeTab) return;\r\n  // 加载对应视图组件...\r\n}, { immediate: true, deep: true });\r\n</script>\r\n```\r\n\r\n## 对于复杂的用例\r\n\r\n你要时刻记住，`ipcRefs` 是用来共享\"状态\"的，而不是共享\"数据\"的。它的数据量必须是极小极简单的。\r\n\r\n当有时我们预料到数据较多较复杂时，使用 `ipcRefs` 会导致前端的状态树过于庞大，内存占用过多，性能下降。毕竟数据在内存中真实地存在了至少两份，且内容在通信时会不可避免地有序列化的开销。\r\n\r\n此时，我们就需要像编写传统的后端应用程序一样，在 embed 中编写一些 `browse.action.ts` 和 `read.action.ts`，前端通过 `aurora.ipc.execute` 调用它们获取所需的、小范围的数据。**注意：这些 browse 和 read 端点必须在 embed 中实现，而非在前端直连 server 调用。** embed 中的 browse/read 端点负责向 server 发起请求，并可选择性地进行缓存处理。\r\n\r\n当数据有任何更新时，我们推送一个更改的事件（`app:*:changed`），里面仅包括更改的内容 id 和时间戳。前端组件通过监听这些事件来了解数据的变更范围，然后按需重新调用查询端点，获取最新的数据。\r\n\r\n假设，我们正在开发一个 `space` 模块，一个用户可能会有无数个空间，很显然，这不是数据量极小极简单的场景。我们不希望将所有内容数据都推送到 `ipcRefs`，而是只在内容发生变更时通知前端。\r\n\r\n```ts\r\n// /app/modules/space/$events/content.event.ts\r\nexport interface _ {\r\n  'app:space:changed': { // 内容变更通知（只推送 id + 时间戳）\r\n    spaceId: string;\r\n    timestamp: number;\r\n  };\r\n}\r\n```\r\n\r\n### embed 中的 browse/read 端点示例\r\n\r\n当数据复杂时，应在 embed 中创建 browse 和 read 端点，前端通过 `aurora.ipc.execute` 调用。`Result` 类型应通过 `stargate.$types.results` 从 server 自动推导，而非手动定义，以确保与后端返回类型始终同步：\r\n\r\n```ts\r\n// /app/modules/space/browse.action.ts\r\nimport type { MilkioContext, MilkioMeta } from '../../../.milkio/declares.ts';\r\nimport { stargate } from '../../utils/stargate.ts';\r\n\r\nexport const meta: MilkioMeta = {};\r\n\r\ntype Params = {\r\n  type?: string;\r\n  cursor?: string;\r\n  limit?: number;\r\n};\r\n\r\ntype Result = (typeof stargate.$types.results)['/space/browse'];\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  context.logger.info('端点请求参数 (browse.action.ts)', JSON.stringify(params));\r\n\r\n  const [error, result] = await stargate.execute('/space/browse', {\r\n    params: {\r\n      type: params.type,\r\n      cursor: params.cursor,\r\n      limit: params.limit,\r\n    },\r\n  });\r\n  if (error) {\r\n    context.logger.error('远程调用失败 (browse.action.ts)', JSON.stringify(error));\r\n    throw error;\r\n  }\r\n\r\n  const data = {\r\n    data: result?.data ?? [],\r\n    cursor: result?.cursor,\r\n  };\r\n  context.logger.info('端点请求结果 (browse.action.ts)', JSON.stringify(data));\r\n\r\n  return data;\r\n}\r\n```\r\n\r\n```ts\r\n// /app/modules/space/read.action.ts\r\nimport type { MilkioContext, MilkioMeta } from '../../../.milkio/declares.ts';\r\nimport { stargate } from '../../utils/stargate.ts';\r\n\r\nexport const meta: MilkioMeta = {};\r\n\r\ntype Params = {\r\n  id: string;\r\n};\r\n\r\ntype Result = (typeof stargate.$types.results)['/space/read'];\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  context.logger.info('端点请求参数 (read.action.ts)', JSON.stringify(params));\r\n\r\n  const [error, result] = await stargate.execute('/space/read', {\r\n    params: {\r\n      id: params.id,\r\n    },\r\n  });\r\n  if (error) {\r\n    context.logger.error('远程调用失败 (read.action.ts)', JSON.stringify(error));\r\n    throw error;\r\n  }\r\n\r\n  const data = {\r\n    data: result?.data,\r\n  };\r\n  context.logger.info('端点请求结果 (read.action.ts)', JSON.stringify(data));\r\n\r\n  return data;\r\n}\r\n```\r\n\r\n前端调用方式：\r\n\r\n```vue\r\n<script setup lang=\"ts\">\r\nconst aurora = await useAurora();\r\n\r\n// 通过 embed 获取空间列表（而非直接调用 server）\r\nconst [error, result] = await aurora.ipc.execute('/space/browse', {\r\n  params: { type: 'plan' },\r\n});\r\n</script>\r\n```\r\n\r\n## 测试\r\n\r\n你应该在对应模块的目录下创建一个 `__TEST__.test.ts`，在里面存放该模块所有相关的测试代码，并且在每次编写完成代码之后，运行一遍相关的测试。使用 **Vitest** 作为测试运行器。\r\n\r\n### generateParams 是必填字段\r\n\r\n每次调用 `world.execute` 都必须显式指定 `generateParams`，不能省略：\r\n\r\n- **`generateParams: true`**：自动生成符合接口类型定义的随机参数。适用于 `adjust` 调试测试，或参数全部可随机生成的场景。如果同时提供了 `params`，则 `params` 中指定的字段使用你的值，其余字段自动生成。\r\n- **`generateParams: false`**：不自动生成参数，仅使用你提供的 `params`。**当你手动指定了 `params` 时必须设为 `false`**，否则 TypeScript 会报类型错误——因为 `generateParams: true` 的分支要求参数类型为可选，与手动传入的完整参数类型不兼容。\r\n\r\n```ts\r\n// 正确：调试时用 true 自动生成\r\nawait world.execute('/note/add-directory', { generateParams: true });\r\n\r\n// 正确：手动参数 + generateParams: false\r\nconst [error, result] = await world.execute('/note/browse-directory', {\r\n  generateParams: false,\r\n  params: { spaceId, directoryId: '' },\r\n});\r\n\r\n// 正确：无参数时也必须显式设为 false\r\nconst [error, result] = await world.execute('/audio/init', { generateParams: false });\r\n\r\n// 错误：有 params 但缺少 generateParams，会报类型错误\r\nawait world.execute('/note/browse-directory', { params: { spaceId, directoryId: '' } });\r\n\r\n// 错误：无 params 也没有 generateParams，会报类型错误\r\nawait world.execute('/audio/init', {});\r\n```\r\n\r\n注意，`generateParams: true` 自动生成数据的规则是\"浅层\"的，只针对 `params` 中的浅层参数有效，不会尝试递归生成深层的随机参数。\r\n\r\n### result 属性的非空断言\r\n\r\n`world.execute` 返回的 `result` 中，某些属性类型可能为 `null` 或 `undefined`（如 `result.data`、`result.voice` 等）。TypeScript 不会从 `expect(...).not.toBeNull()` 推断类型窄化，因此在断言后访问这些属性仍需使用非空断言 `!`：\r\n\r\n```ts\r\n// 错误：result.data 可能为 undefined，TS 报错\r\nconst id = resultAddDir.data.id;\r\n\r\n// 正确：使用 ! 非空断言\r\nconst id = resultAddDir.data!.id;\r\n\r\n// 断言后再访问属性，仍需 !\r\nexpect(resultInit.voice).not.toBeNull();\r\nexpect(resultInit.voice!.volume).toBe(50);\r\n```\r\n\r\n### 错误处理\r\n\r\n在测试代码中，使用以下方式检查错误类型（`kind` + `code` 收窄）：\r\n\r\n```typescript\r\n// 正确：先确认是 fail，再按 code 收窄\r\nif (error?.kind === \"fail\" && error.code === \"VERIFICATION_CODE_INVALID\") {\r\n    // 处理验证码无效的错误\r\n}\r\n\r\nif (!(error?.kind === \"fail\" && error.code === \"VERIFICATION_CODE_INVALID\")) {\r\n    // 处理其他类型的错误\r\n}\r\n```\r\n\r\n**禁止**使用 keyed-map 写法，尽管它们可能在某些情况下运行正常，但会导致 TypeScript 类型推断不准确：\r\n\r\n```typescript\r\n// 错误！禁止使用\r\nexpect(error?.code).toBe(\"VERIFICATION_CODE_INVALID\");     // 缺少 kind 收窄\r\nexpect(error?.VERIFICATION_CODE_INVALID).toBeDefined();    // 旧 keyed-map 写法\r\n```\r\n\r\n### 测试用例注释\r\n\r\n编写的测试需要包含详尽的中文注释，确保可读性。包括在测试开头添加多行注释，描述测试的意图，以及在测试的实际代码中，描述每一个步骤的作用。\r\n\r\n```ts\r\n/**\r\n * 嵌套目录测试\r\n * 验证目录嵌套和子目录内笔记的 CRUD：\r\n * 1. 在根目录创建文件夹 A\r\n * 2. 在文件夹 A 内创建子文件夹 B\r\n * 3. 在子文件夹 B 内创建笔记\r\n * 4. 浏览子文件夹 B（应含笔记）\r\n * 5. 浏览文件夹 A（应含子文件夹 B，无笔记）\r\n */\r\ntest('nestedDirectory', async () => {\r\n  const [_context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n\r\n  // 创建文件夹 A\r\n  const [errorAddA, resultAddA] = await world.execute('/note/add-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, parentId: '', name: '文件夹A' },\r\n  });\r\n  if (errorAddA) throw fail('创建文件夹A失败', errorAddA);\r\n  const dirAId = resultAddA.data!.id;\r\n\r\n  // 在文件夹 A 内创建子文件夹 B\r\n  const [errorAddB, resultAddB] = await world.execute('/note/add-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, parentId: dirAId, name: '子文件夹B' },\r\n  });\r\n  if (errorAddB) throw fail('创建子文件夹B失败', errorAddB);\r\n  const dirBId = resultAddB.data!.id;\r\n\r\n  // 在子文件夹 B 内创建笔记\r\n  const [errorAddNote, resultAddNote] = await world.execute('/note/add-note', {\r\n    generateParams: false,\r\n    params: { spaceId, parentId: dirBId, title: '子笔记' },\r\n  });\r\n  if (errorAddNote) throw fail('创建子笔记失败', errorAddNote);\r\n\r\n  // 浏览子文件夹 B（应含笔记）\r\n  const [errorBrowseB, resultBrowseB] = await world.execute('/note/browse-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, directoryId: dirBId },\r\n  });\r\n  if (errorBrowseB) throw fail('浏览子文件夹B失败', errorBrowseB);\r\n  expect(resultBrowseB.notes.length).toBe(1);\r\n  expect(resultBrowseB.notes[0].title).toBe('子笔记');\r\n\r\n  // 浏览文件夹 A（应含子文件夹 B，无笔记）\r\n  const [errorBrowseA, resultBrowseA] = await world.execute('/note/browse-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, directoryId: dirAId },\r\n  });\r\n  if (errorBrowseA) throw fail('浏览文件夹A失败', errorBrowseA);\r\n  expect(resultBrowseA.directories.length).toBe(1);\r\n  expect(resultBrowseA.directories[0].id).toBe(dirBId);\r\n  expect(resultBrowseA.notes.length).toBe(0);\r\n});\r\n```\r\n\r\n### 测试策略建议\r\n\r\n* **成功路径测试**：验证动作在正常情况下的行为是否符合预期。\r\n* **失败路径测试**：**至关重要**。应编写测试来验证代码在边界条件、异常输入或非法操作下的处理逻辑是否正确（例如，传递非法 ID、重复创建、权限不足等）。\r\n\r\n### 测试用例示例\r\n\r\n以下示例展示了 embed 工程中针对不同场景的标准测试写法：\r\n\r\n**调试测试 (`adjust`)**：\r\n\r\n调试测试用于在开发过程中快速验证接口是否可正常调用，不做断言，仅用于调试和观察返回值。\r\n\r\n```ts\r\nimport { expect, test } from 'vite-plus/test';\r\nimport { astra } from '../../utils/test.ts';\r\n\r\ntest('adjust', async () => {\r\n  const [_context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n  // 调试：执行动作，generateParams 会自动生成符合接口定义的随机参数\r\n  await world.execute('/note/add-directory', { generateParams: true });\r\n});\r\n```\r\n\r\n**基础 CRUD 测试 (`basic`)**：\r\n\r\n```ts\r\nimport { expect, test } from 'vite-plus/test';\r\nimport { astra } from '../../utils/test.ts';\r\n\r\n/**\r\n * 基础创建与查询测试\r\n * 验证数据的创建和查询流程：\r\n * 1. 调用 add-directory 接口创建文件夹\r\n * 2. 浏览根目录，断言文件夹存在\r\n * 3. 在文件夹中创建笔记\r\n * 4. 浏览文件夹，断言笔记存在\r\n * 5. 删除笔记\r\n * 6. 删除文件夹\r\n * 7. 浏览根目录，断言为空\r\n */\r\ntest('basic', async () => {\r\n  const spaceId = 'spc-test';\r\n  const [_context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n\r\n  // 1. 创建文件夹 A\r\n  const [errorAddDir, resultAddDir] = await world.execute('/note/add-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, parentId: '', name: '文件夹A' },\r\n  });\r\n  if (errorAddDir) throw fail('创建文件夹失败', errorAddDir);\r\n  expect(resultAddDir.data).not.toBeUndefined();\r\n  const dirAId = resultAddDir.data!.id;\r\n\r\n  // 2. 浏览根目录（应含文件夹 A）\r\n  const [errorBrowse1, resultBrowse1] = await world.execute('/note/browse-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, directoryId: '' },\r\n  });\r\n  if (errorBrowse1) throw fail('浏览根目录失败', errorBrowse1);\r\n  expect(resultBrowse1.directories.length).toBe(1);\r\n  expect(resultBrowse1.directories[0].id).toBe(dirAId);\r\n\r\n  // 3. 在文件夹 A 中创建笔记\r\n  const [errorAddNote, resultAddNote] = await world.execute('/note/add-note', {\r\n    generateParams: false,\r\n    params: { spaceId, parentId: dirAId, title: '笔记1' },\r\n  });\r\n  if (errorAddNote) throw fail('创建笔记失败', errorAddNote);\r\n  expect(resultAddNote.data).not.toBeUndefined();\r\n  const noteId = resultAddNote.data!.id;\r\n\r\n  // 4. 浏览文件夹 A（应含笔记）\r\n  const [errorBrowseA, resultBrowseA] = await world.execute('/note/browse-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, directoryId: dirAId },\r\n  });\r\n  if (errorBrowseA) throw fail('浏览文件夹A失败', errorBrowseA);\r\n  expect(resultBrowseA.notes.length).toBe(1);\r\n  expect(resultBrowseA.notes[0].id).toBe(noteId);\r\n\r\n  // 5. 删除笔记\r\n  const [errorDeleteNote, resultDeleteNote] = await world.execute('/note/delete-note', {\r\n    generateParams: false,\r\n    params: { spaceId, id: noteId },\r\n  });\r\n  if (errorDeleteNote) throw fail('删除笔记失败', errorDeleteNote);\r\n\r\n  // 6. 删除文件夹\r\n  const [errorDeleteDir, resultDeleteDir] = await world.execute('/note/delete-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, id: dirAId },\r\n  });\r\n  if (errorDeleteDir) throw fail('删除文件夹失败', errorDeleteDir);\r\n\r\n  // 7. 浏览根目录（应为空）\r\n  const [errorBrowseEnd, resultBrowseEnd] = await world.execute('/note/browse-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, directoryId: '' },\r\n  });\r\n  if (errorBrowseEnd) throw fail('浏览根目录失败', errorBrowseEnd);\r\n  expect(resultBrowseEnd.directories.length).toBe(0);\r\n  expect(resultBrowseEnd.notes.length).toBe(0);\r\n});\r\n```\r\n\r\n**状态初始化测试**：\r\n\r\n验证 `init` 类动作返回的默认状态是否正确：\r\n\r\n```ts\r\n/**\r\n * 音频初始化测试\r\n * 验证 init 后各通道的默认值\r\n */\r\ntest('initDefaults', async () => {\r\n  const [_context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n\r\n  const [errorInit, resultInit] = await world.execute('/audio/init', { generateParams: false });\r\n  if (errorInit) throw fail('音频初始化失败', errorInit);\r\n\r\n  // voice 通道：默认音量 50，playMode 'stop'，current 为 null\r\n  expect(resultInit.voice).not.toBeNull();\r\n  expect(resultInit.voice!.volume).toBe(50);\r\n  expect(resultInit.voice!.playMode).toBe('stop');\r\n  expect(resultInit.voice!.current).toBeNull();\r\n\r\n  // music 通道：默认音量 50，playMode 'loop'，current 为 null\r\n  expect(resultInit.music).not.toBeNull();\r\n  expect(resultInit.music!.volume).toBe(50);\r\n  expect(resultInit.music!.playMode).toBe('loop');\r\n  expect(resultInit.music!.current).toBeNull();\r\n});\r\n```\r\n\r\n**移动/排序测试**：\r\n\r\n验证数据在目录间移动或排序的正确性：\r\n\r\n```ts\r\n/**\r\n * 移动笔记测试\r\n * 验证笔记在目录间移动：\r\n * 1. 创建文件夹 A 和文件夹 B\r\n * 2. 在文件夹 A 中创建笔记\r\n * 3. 将笔记移到文件夹 B 内\r\n * 4. 浏览文件夹 A（应无笔记）\r\n * 5. 浏览文件夹 B（应含该笔记）\r\n */\r\ntest('moveNote', async () => {\r\n  const spaceId = 'spc-test';\r\n  const [_context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n\r\n  // 创建文件夹 A\r\n  const [errorAddA, resultAddA] = await world.execute('/note/add-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, parentId: '', name: '文件夹A' },\r\n  });\r\n  if (errorAddA) throw fail('创建文件夹A失败', errorAddA);\r\n  const dirAId = resultAddA.data!.id;\r\n\r\n  // 创建文件夹 B\r\n  const [errorAddB, resultAddB] = await world.execute('/note/add-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, parentId: '', name: '文件夹B' },\r\n  });\r\n  if (errorAddB) throw fail('创建文件夹B失败', errorAddB);\r\n  const dirBId = resultAddB.data!.id;\r\n\r\n  // 在文件夹 A 中创建笔记\r\n  const [errorAddNote, resultAddNote] = await world.execute('/note/add-note', {\r\n    generateParams: false,\r\n    params: { spaceId, parentId: dirAId, title: '待移动笔记' },\r\n  });\r\n  if (errorAddNote) throw fail('创建笔记失败', errorAddNote);\r\n  const noteId = resultAddNote.data!.id;\r\n\r\n  // 将笔记从文件夹 A 移到文件夹 B 内\r\n  const [errorMove, resultMove] = await world.execute('/note/move', {\r\n    generateParams: false,\r\n    params: {\r\n      spaceId,\r\n      sourcePathIds: [dirAId],\r\n      movingId: noteId,\r\n      targetPathIds: [],\r\n      targetId: dirBId,\r\n      position: 'inside',\r\n    },\r\n  });\r\n  if (errorMove) throw fail('移动笔记失败', errorMove);\r\n\r\n  // 浏览文件夹 A（应无笔记）\r\n  const [errorBrowseA, resultBrowseA] = await world.execute('/note/browse-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, directoryId: dirAId },\r\n  });\r\n  if (errorBrowseA) throw fail('浏览文件夹A失败', errorBrowseA);\r\n  expect(resultBrowseA.notes.length).toBe(0);\r\n\r\n  // 浏览文件夹 B（应含该笔记）\r\n  const [errorBrowseB, resultBrowseB] = await world.execute('/note/browse-directory', {\r\n    generateParams: false,\r\n    params: { spaceId, directoryId: dirBId },\r\n  });\r\n  if (errorBrowseB) throw fail('浏览文件夹B失败', errorBrowseB);\r\n  expect(resultBrowseB.notes.length).toBe(1);\r\n  expect(resultBrowseB.notes[0]!.id).toBe(noteId);\r\n});\r\n```",
    "docs/point.md": "# Point\r\n\r\n## 概述\r\n\r\n端点是若干个以 `.action.ts` 结尾的文件，使用小写字母+中划线命名，采用动词命名。\r\n\r\n通常，一个模块会包含五个端点，即 BREAD。BREAD 是 browse.action.ts (浏览)、read.action.ts(读取单个)、edit.action.ts(编辑)、add.action.ts(添加)、delete.action.ts(删除) 的缩写。\r\n\r\n一般而言，每个模块，都包含这五个端点，但是，有些模块可能不需要这么多，例如一些只读性质的模块。又或者，可能会拥有更多的端点，例如用户模块，除了以上五个端点之外，还包含 login.action.ts、logout.action.ts、register.action.ts 这种特殊的端点。\r\n\r\n端点需要存放在 `/app/modules` 目录下。例如：\r\n\r\n```\r\n/app/modules/user/$databases/user.table.ts\r\n/app/modules/user/edit.action.ts\r\n```\r\n\r\n## 示例\r\n\r\n```ts\r\n// /app/modules/application/add.action.ts\r\nimport { MilkioContext, MilkioMeta } from '../../../.milkio/declares.ts';\r\n\r\nexport const meta: MilkioMeta = {\r\n  allow: [],\r\n};\r\n\r\ntype Params = {\r\n  data: ArticleInsert;\r\n}\r\n\r\ntype Result = {\r\n  id: string;\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  const id = ...;\r\n  // 执行添加逻辑...\r\n  return { id };\r\n};\r\n```\r\n\r\n这是一个典型的端点。必须强调，你必须显式定义 `Params` 和 `Result` 的类型，不编写类型由编译器推导是严格禁止的。\r\n\r\n注意，返回值必须是一个 object 对象，你不能返回数组或者原始类型（如字符串、数字等）。因此，示例中的返回值使用对象包裹，而不是直接返回。\r\n\r\n## 类型校验\r\n\r\n`Params` 类型决定了你的端点可以接受哪些值。Milkio 会自动使用 typia 来确保接收到的值符合 `Params` 的类型。任何不符合你方法预期类型的输入都将被拒绝，而任何符合类型要求的额外属性将被移除。\r\n\r\nTypia 通过分析你的代码并执行 AOT（提前）编译，将代码中的验证部分转换为适合你类型的专有代码。即使代码被捆绑成了普通的 javascript 类型校验也依然有效。\r\n\r\n## 测试\r\n\r\n你必须编写完善且详细的测试用例，采用集成测试的思路，通过按照指定顺序调用一个或多个端点，最终验证数据是否被正确处理（你每次运行测试之前，状态/数据库都会被清空）。\r\n\r\n你应该在对应模块的目录下创建一个 `__TEST__.test.ts`，在里面存放该模块所有相关的测试代码。每个模块只应有一个测试文件，将模块中所有端点的测试集中放在这个文件中。\r\n\r\n```ts\r\n// /app/modules/application/__TEST__.test.ts\r\ntest(\"test-bar\", async () => {\r\n    const [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n    const [error, result] = await world.execute(\"/application/add\", {\r\n        generateParams: true\r\n    });\r\n    if (error) throw fail('测试失败', error);\r\n    expect(typeof result.id).toBe('string');\r\n });\r\n```\r\n\r\n注意，测试过程中是启动了真实 HTTP 服务器，因此，工程代码与测试代码没有运行在一个实例中，他们内存不共享。\r\n\r\n## 日志\r\n\r\n你必须编写详尽的日志，以便在排查问题时能够快速定位原因。Milkio 提供了 `context.logger` 日志器，支持 `info` 和 `error` 两个方法。\r\n\r\n### `context.logger.info(message, ...data)`\r\n\r\n记录常规信息日志，用于记录关键的业务流程节点和操作结果。\r\n\r\n```ts\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n    context.logger.info('端点请求参数 (edit-phone.action.ts)', JSON.stringify(params));\r\n\r\n  // 记录关键业务操作\r\n  context.logger.info('手机号修改成功 (edit-phone.action.ts)', JSON.stringify({\r\n    userId: currentUser.id,\r\n    oldPhone: currentUser.phone,\r\n    newPhone: params.phone,\r\n  }));\r\n\r\n  // 记录外部服务调用结果\r\n  context.logger.info('短信发送结果 (edit-phone.action.ts)', JSON.stringify(result));\r\n  \r\n  const result = { foo: 'bar' };\r\n  context.logger.info('端点请求结果 (edit-phone.action.ts)', JSON.stringify(result));\r\n  \r\n  return result;\r\n};\r\n```\r\n\r\n### `context.logger.error(message, ...data)`\r\n\r\n记录错误日志，用于在业务校验失败或异常情况时记录详细信息。**注意**：`logger.error` 只负责记录日志，不会中断执行流程。如果你需要在记录错误后中断请求，必须在下一行 `throw context.fail(...)`。\r\n\r\n```ts\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  if (!params.phone) {\r\n    // 先记录错误日志，再抛出拒绝\r\n    context.logger.error('新手机号不能为空 (edit-phone.action.ts)', JSON.stringify(params));\r\n    throw context.fail('DATA_NOT_FOUND', undefined);\r\n  }\r\n\r\n  if (!currentUser) {\r\n    context.logger.error('用户不存在 (edit-phone.action.ts)', JSON.stringify(params));\r\n    throw context.fail('DATA_NOT_FOUND', undefined);\r\n  }\r\n};\r\n```\r\n\r\n1. **必须记录关键业务操作**：如登录成功、数据修改、支付创建等，确保重要操作有迹可循。\r\n2. **错误日志必须附带上下文数据**：记录错误时应将相关的参数一并传入，方便排查。例如 `context.logger.error('用户不存在', JSON.stringify(params))` 而非仅 `context.logger.error('用户不存在')`。\r\n3. **消息中标注来源**：在日志消息中用括号标注当前文件名，如 `'用户不存在 (edit-phone.action.ts)'`，方便在海量日志中快速定位来源。\r\n4. **请求与响应日志**:一个合适的 action 端点尽可能保证要有一条参数日志，一条打印返回值日志。当然，没有任何参数，或者没有任何返回值的端点，可以不记录。\r\n5. **还原现场**：日志要尽可能地详细，出现任何问题时，你只能得到日志作为参考。如果不够详细，你将无法推断和修复错误。\r\n6. **对象必须使用 `JSON.stringify` 包裹**：日志中的对象参数必须用 `JSON.stringify()` 序列化后传入，避免某些运行时环境下对象被输出为 `[object Object]` 而丢失信息。例如 `context.logger.info('请求参数', JSON.stringify(params))` 而非 `context.logger.info('请求参数', params)`。\r\n\r\n## 端点编码规范\r\n\r\n在编写端点代码时，你必须遵循以下规则：\r\n\r\n1. **过程式编程**：所有功能采用过程式风格实现。\r\n2. **禁止使用 class、enum 和 interface**：不得在端点代码中使用 `class` 或 `interface` 关键字，所有类型定义必须使用 `type`。对于 enum 类型，可以 `type Qux = 'foo' | 'bar'` 这种为字符串添加类型约束来实现。\r\n3. **禁止私有函数封装**：不得将逻辑封装为仅被调用一两次的非导出函数。这只会增加复杂度和维护成本，且破坏了从上到下线性阅读的代码风格。只有对外导出的函数（如 `export function ... {}`）才是允许的。\r\n4. **详尽的注释**：必须添加详细清晰的注释。修改代码时，若注释与代码不一致，必须同步更新注释。严格确保注释与代码都含义一致。\r\n\r\n```ts\r\n// ❌ 坏例子 1：将逻辑封装到仅被调用一次的私有函数中\r\nasync function createFoo(context: MilkioContext) {\r\n  // ...创建 Foo 的逻辑...\r\n}\r\n\r\nasync function updateBar(context: MilkioContext, id: string) {\r\n  // ...更新 Bar 的逻辑...\r\n}\r\n\r\nasync function notifyUser(context: MilkioContext, userId: string) {\r\n  // ...发送通知的逻辑...\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  // 仅仅是为了\"组织代码\"而拆分出多个函数，实际上每个函数只在这里被调用一次\r\n  // 这增加了代码的复杂度，阅读者需要在多个函数之间跳转才能理解完整流程\r\n  await createFoo(context);\r\n  await updateBar(context, params.id);\r\n  await notifyUser(context, params.userId);\r\n  // ...其余逻辑...\r\n};\r\n```\r\n\r\n```ts\r\n// ❌ 坏例子 2：使用 class 来组织端点逻辑\r\nclass FooService {\r\n  private context: MilkioContext;\r\n\r\n  constructor(context: MilkioContext) {\r\n    this.context = context;\r\n  }\r\n\r\n  async createFoo() {\r\n    // ...创建 Foo 的逻辑...\r\n  }\r\n\r\n  async updateBar(id: string) {\r\n    // ...更新 Bar 的逻辑...\r\n  }\r\n\r\n  async notifyUser(userId: string) {\r\n    // ...发送通知的逻辑...\r\n  }\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  // 端点逻辑不应该用 class 封装，class 增加了不必要的抽象层\r\n  const service = new FooService(context);\r\n  await service.createFoo();\r\n  await service.updateBar(params.id);\r\n  await service.notifyUser(params.userId);\r\n  // ...其余逻辑...\r\n};\r\n```\r\n\r\n```ts\r\n// ❌ 坏例子 3：封装仅被调用两次的工具函数，破坏了线性阅读\r\nfunction buildNotificationPayload(userId: string, message: string) {\r\n  // ...构建通知载荷的逻辑...\r\n}\r\n\r\nasync function createFoo(context: MilkioContext) {\r\n  // ...创建 Foo 的逻辑...\r\n  const payload = buildNotificationPayload(context.userId, 'Foo 已创建');\r\n  // ...发送通知...\r\n}\r\n\r\nasync function updateBar(context: MilkioContext) {\r\n  // ...更新 Bar 的逻辑...\r\n  const payload = buildNotificationPayload(context.userId, 'Bar 已更新');\r\n  // ...发送通知...\r\n}\r\n\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  await createFoo(context);\r\n  await updateBar(context);\r\n  // ...其余逻辑...\r\n};\r\n```\r\n\r\n```ts\r\n// ✅ 好例子：采用过程式风格，从上到下线性阅读，逻辑一目了然\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  // 创建 Foo\r\n  // ...创建 Foo 的逻辑...\r\n\r\n  // 更新 Bar\r\n  // ...更新 Bar 的逻辑...\r\n\r\n  // 发送通知\r\n  // ...发送通知的逻辑...\r\n\r\n  // 返回结果\r\n  return { ... };\r\n};\r\n```\r\n\r\n```ts\r\n// ✅ 好例子：即使逻辑较长，也保持在 handler 内部线性展开，辅以清晰的注释分段\r\nexport async function handler(\r\n  context: MilkioContext,\r\n  params: Params,\r\n): Promise<Result> {\r\n  // ========================================================================\r\n  // 参数校验与预处理\r\n  // ========================================================================\r\n  // ...校验参数的逻辑...\r\n  // ...预处理数据的逻辑...\r\n\r\n  // ========================================================================\r\n  // 核心业务逻辑\r\n  // ========================================================================\r\n  // ...执行主要业务逻辑...\r\n\r\n  // ========================================================================\r\n  // 数据持久化\r\n  // ========================================================================\r\n  // ...写入数据库的逻辑...\r\n\r\n  // ========================================================================\r\n  // 后置操作（通知、日志等）\r\n  // ========================================================================\r\n  // ...发送通知的逻辑...\r\n  // ...记录日志的逻辑...\r\n\r\n  // ========================================================================\r\n  // 返回结果\r\n  // ========================================================================\r\n  return { ... };\r\n};\r\n```",
    "docs/stargate.md": "# Stargate\r\n\r\n## 最简单的示例\r\n\r\n```ts\r\nconst [error, result, details] = await stargate.execute(\"/foo/bar\", {\r\n  params: {\r\n    hello: \"Milkio\",\r\n  },\r\n});\r\n\r\nif (error) {\r\n  // 处理错误..\r\n}\r\n\r\nresult;\r\n```\r\n\r\n`execute` 方法始终返回一个包含三个成员的数组，`[error,result,details]`。\r\n\r\n- `error`：错误信息（失败时存在，成功时为 `null`）\r\n- `result`：成功返回的数据（失败时为 `null`）\r\n- `details`：一些杂项数据\r\n\r\n你只有在显式判断 `error === null` 时，才能安全使用 `result`，否则 typescript 编译器会报错。\r\n\r\n### 为什么要这样设计？\r\n\r\n比如说 golang 中，我们经常会看到：\r\n\r\n```go\r\nif err != nil {\r\n  fmt.Printf(\"错误: %v\\n\", err)\r\n  return\r\n}\r\n```\r\n\r\n通过这种方式来处理错误，这和 stargate 很像，stargate 通过这种限制你必须先处理错误，再使用 result 中的值的方式。尽管有些啰嗦，但是这在限制你写出健壮的代码。\r\n\r\n## 在 vue 工程中处理失败\r\n\r\n**重要**：在 vue 前端工程中，不得直接使用 `stargate.execute` 调用后端服务器端点。前端必须通过 `aurora.ipc.execute` 调用 embed 端点，由 embed 统一代理与后端的通信。详见 SKILL.md 中\"前端必须通过 embed 与后端通信\"章节。\r\n\r\n前端通过 `aurora.ipc.execute` 调用 embed 端点时，失败处理方式与直接使用 `stargate.execute` 相同。\r\n\r\n返回值仍为 `[failure, result, details]`，失败对象带 `kind`：\r\n\r\n- `failure.kind === \"fail\"`：用 `failure.code` 判断具体业务错误，`failure.data` 是类型收窄后的数据；\r\n- `failure.kind === \"fault\"`：意料外/内部错误，只有通用 `code: \"INTERNAL_SERVER_ERROR\"`，没有真实 fault-code/data，应显示错误页并带上 `details.executeId`。\r\n\r\n不要再用 `'YOUR_ERR_CODE' in error` 这种 keyed-map 写法。\r\n\r\n```ts\r\nconst aurora = await useAurora();\r\nconst [failure, result, details] = await aurora.ipc.execute(\"/foo/bar\", {\r\n  params: {\r\n    hello: \"Milkio\",\r\n  },\r\n});\r\n\r\nif (failure) {\r\n    if (failure.kind === \"fault\") {\r\n        // 意料外的错误：错误页 + executeId\r\n        throw showError({ data: { failure, result, details } });\r\n    }\r\n    switch (failure.code) {\r\n        case 'USER_EMAIL_UPDATE_LIMIT':\r\n            return alert('你最近修改过邮箱了，从上次修改之日起7天内不能重复修改');\r\n        case 'USER_EMAIL_EXIST':\r\n            return alert('该邮箱已被其他用户使用');\r\n        default:\r\n            return alert('操作失败');\r\n    }\r\n}\r\n\r\nresult;\r\n```\r\n\r\n这里只是简单地使用 `alert` 弹出了错误消息，实际的业务开发中，你不得使用如此简陋的方式来展示错误消息。你应该遵循：\r\n\r\n- 对于后台式的执行错误，认为应该不打扰用户的，例如后台定时上报数据，你可以简单地忽略，不做任何错误处理。\r\n- 对于可接受的错误，例如用户输入错误，你应该在页面友好地提示，例如在输入框下方展示错误信息，或者弹出 toast（根据你使用的 UI 框架来定），并让用户可以继续操作。\r\n- 对于需要显式要求用户操作的错误，例如需要用户主动点击重试、或者需要用户输入验证码等，你应该采用弹窗等交互方式，让用户可以继续操作。\r\n- 对于意料外的、无法重试的、属于程序异常的错误，你应该直接显示 nuxt 的错误页面，阻止用户的其他操作，不要静默处理，这很可能让错误不受控地扩散甚至产生脏数据。\r\n\r\n不得忽略错误，宁愿中断用户的操作（使用 `showError({ data: { failure, result, details } })` 直接显示 nuxt 的错误页面）也不要忽略任何错误。必须要阻止错误不受控地扩散甚至产生脏数据。\r\n\r\n## 在 milkio 工程中处理失败\r\n\r\n由于 milkio 工程通常不是与用户交互的一线，所以不需要处理失败，只需要在执行失败时，直接抛出错误即可。\r\n\r\n`stargate.execute` 返回的 `failure` 有两种 `kind`：\r\n\r\n- `\"fail\"`：预期内的业务拒绝，带真实 `code` 与 `data`；\r\n- `\"fault\"`：未意料/内部错误，对客户端只暴露通用字符串码 `\"INTERNAL_SERVER_ERROR\"`，真实 fault-code/data/stack 只留在产生错误的那台服务的日志里。\r\n\r\n**重要**：当 milkio 工程作为中间层（如 embed）调用其他 milkio 工程并需要将失败向上传递时，直接 `throw failure` 即可（不要重新包装成 `context.fail(...)`）。失败对象自带 `$milkioFailure` 标记，服务端能识别并保持 kind/code；这样 fail 会继续按 warn 处理，fault 会继续按 error 处理。\r\n\r\n```ts\r\nconst [failure, result, details] = await stargate.execute(\"/foo/bar\", {\r\n  params: {\r\n    hello: \"Milkio\",\r\n  },\r\n});\r\n\r\nif (failure) throw failure;\r\n\r\nresult;\r\n```\r\n\r\n如果你需要根据失败类型做处理：`failure.kind === \"fail\"` 时可按 `failure.code` 分支并使用 `failure.data`；`failure.kind === \"fault\"` 时只应记录/上报，不要依赖具体 fault-code（客户端拿不到）。\r\n\r\n## 在测试（astra）中处理失败\r\n\r\n`astra.createMirrorWorld()` 返回的 `world.execute` / `world.emit` 内部就是通过客户端 `stargate` 访问 dev server，所以测试侧的失败返回值与客户端侧**完全一致**，类型也是同一个（`@milkio/astra` 直接取 stargate 实例的 `$types.failure`）：\r\n\r\n- 返回形状同样是 `[failure, result, details]`；\r\n- `failure.kind === \"fail\"` / `\"fault\"` 的区分、`failure.code` 收窄、`failure.data` 的类型都与客户端侧相同；\r\n- 客户端自己合成的传输层故障（`kind: \"fault\"` + `code: \"NETWORK_ERROR\"` / `\"REQUEST_TIMEOUT\"`）在测试侧同样可能返回。\r\n\r\n```ts\r\nconst [context, fail, world] = await astra.createMirrorWorld(import.meta.url);\r\n\r\nconst [failure, result] = await world.execute(\"/foo/bar\", {\r\n  generateParams: false,\r\n  params: {},\r\n});\r\n\r\nif (failure) {\r\n  if (failure.kind === \"fail\" && failure.code === \"USER_EMAIL_EXIST\") {\r\n    // failure.data 已按该 fail-code 收窄\r\n    expect(failure.data.email).toBe(\"milkio@example.com\");\r\n  }\r\n  if (failure.kind === \"fault\") {\r\n    // 意料外错误或传输层故障：仅记录/上报，并让测试失败\r\n    throw fail(\"Milkio did not execute successfully\", failure);\r\n  }\r\n}\r\n\r\nresult;\r\n```\r\n\r\n**不要再用 `'YOUR_ERR_CODE' in error` 判断失败类型**：这是旧版 keyed-map 协议的写法，客户端侧与测试侧都已不再使用；也不存在 `error.YOUR_ERR_CODE` 这种按错误码取 `data` 的方式。\r\n\r\n## 调用 Stream 端点\r\n\r\n除了普通的 action 端点，Milkio 还支持 stream 端点（`.stream.ts`）。调用 stream 时，路径末尾需要加 `~` 后缀，`stargate.execute` 会返回一个 `AsyncGenerator`：\r\n\r\n```ts\r\nconst [failure, iterator, details] = await stargate.execute('/event/watch~', {\r\n  params: {},\r\n});\r\n\r\nif (failure) {\r\n  // 连接失败处理\r\n  throw failure;\r\n}\r\n\r\n// iterator 是一个 AsyncGenerator，持续接收服务端推送的数据\r\nfor await (const chunk of iterator) {\r\n  const [chunkFailure, chunkData] = chunk;\r\n  if (chunkFailure) {\r\n    // 数据块失败\r\n    console.error(chunkFailure);\r\n    continue;\r\n  }\r\n  // 处理推送数据\r\n  console.log(chunkData);\r\n}\r\n```\r\n\r\n**与 action 调用的区别**：\r\n- 路径以 `~` 结尾（如 `/event/watch~`）\r\n- 成功时返回 `[null, AsyncGenerator, details]`\r\n- `AsyncGenerator` 的每个 yield 值为 `[chunkFailure, chunkData]` 格式\r\n- 连接会持续保持，直到服务端关闭或客户端主动 break\r\n\r\n## 事件钩子\r\n\r\nStargate 实例支持注册事件钩子，用于在请求的不同阶段进行拦截处理。详细用法请参阅 `./docs/create-stargate.md`。\r\n\r\n- `stargate.on('milkio:executeBefore', ...)` — 请求执行前\r\n- `stargate.on('milkio:fetchBefore', ...)` — HTTP 请求发送前（可用于签名）\r\n- `stargate.on('milkio:executeError', ...)` — 请求执行出错时\r\n\r\n## 缓存与重试\r\n\r\nStargate 支持请求级别的缓存策略和重试策略：\r\n\r\n```ts\r\nconst [error, result, details] = await stargate.execute('/user/read-my', {\r\n  cacheStrategy: 'throttle',  // 'off' | 'fallback' | 'throttle'\r\n  cacheThrottleMs: 5000,\r\n  onCacheHit: (cachedResult) => {\r\n    // 缓存命中回调\r\n  },\r\n  retryStrategy: true,  // true=重试2次, 或指定次数\r\n});\r\n```\r\n\r\n详细配置请参阅 `./docs/create-stargate.md`。",
    "docs/stream.md": "# Stream\r\n\r\n## 概述\r\n\r\nStream 端点（`.stream.ts`）是 Milkio 中实现服务端实时推送的机制。与 action 端点的一次性请求-响应不同，stream 端点基于 Server-Sent Events (SSE) 建立持久连接，服务端可以持续向客户端推送数据。\r\n\r\n## 文件规范\r\n\r\n### 命名与位置\r\n\r\nStream 文件以 `.stream.ts` 结尾，放在模块目录下，与 `.action.ts` 文件同级：\r\n\r\n```\r\napp/modules/event/\r\n├── watch.stream.ts      # 事件订阅流\r\n└── ...\r\n```\r\n\r\n### 路由映射\r\n\r\nStream 文件的路由映射规则与 action 相同：`app/modules/event/watch.stream.ts` 映射为 `/event/watch~`。注意路径末尾的 `~` 后缀用于区分 stream 和 action。\r\n\r\n## 定义 Stream 端点\r\n\r\nStream 端点使用 `async function*`（异步生成器）定义：\r\n\r\n```ts\r\n// /app/modules/event/watch.stream.ts\r\nimport { createFlow } from 'milkio';\r\nimport type { MilkioContext, MilkioMeta } from '../../../.milkio/declares';\r\n\r\nexport const meta: MilkioMeta = {};\r\n\r\nexport async function* handler(\r\n  context: MilkioContext,\r\n  params: {},\r\n): AsyncGenerator<{ key: string; data: any }> {\r\n  const flow = createFlow<{ key: string; data: any }>();\r\n\r\n  // 监听所有事件\r\n  context._.on('*', ({ key, value }) => {\r\n    // 只推送特定前缀的事件\r\n    if (!key.startsWith('app:')) return;\r\n    flow.emit({ key, data: value });\r\n  });\r\n\r\n  // 触发生命周期事件，通知前端初始化完成\r\n  void context.emit('life-cycle:mounted', context).then(() =>\r\n    flow.emit({ key: 'app:life-cycle:after-mounted', data: undefined })\r\n  );\r\n  flow.emit({ key: 'life-cycle:mounted', data: undefined });\r\n\r\n  // 持续产出数据\r\n  for await (const chunk of flow) yield chunk;\r\n}\r\n```\r\n\r\n## 核心概念\r\n\r\n### createFlow\r\n\r\n`createFlow` 是 Milkio 提供的流控工具，用于创建一个可手动触发的异步流：\r\n\r\n```ts\r\nimport { createFlow } from 'milkio';\r\n\r\nconst flow = createFlow<{ key: string; data: any }>();\r\n\r\n// 手动向流中推送数据\r\nflow.emit({ key: 'app:tabs', data: tabData });\r\n\r\n// 通过 for await 消费流\r\nfor await (const chunk of flow) {\r\n  yield chunk;\r\n}\r\n```\r\n\r\n`createFlow` 桥接了事件回调和异步生成器——你可以在任意回调中调用 `flow.emit()`，而生成器会自动将数据推送给客户端。\r\n\r\n### context._.on()\r\n\r\n`context._.on('*', handler)` 用于监听服务端内部的所有事件。`*` 表示通配，监听所有事件。handler 接收 `{ key, value }` 参数，你可以通过 `key` 过滤只推送特定事件。\r\n\r\n### meta 定义\r\n\r\nStream 的 `meta` 与 action 的 `meta` 用法相同：\r\n\r\n```ts\r\nexport const meta: MilkioMeta = {\r\n  allow: [],  // 访问控制\r\n};\r\n```\r\n\r\n## 客户端调用\r\n\r\n前端通过 `stargate.execute` 调用 stream，路径末尾加 `~`：\r\n\r\n```ts\r\nconst [failure, iterator, details] = await stargate.execute('/event/watch~', {\r\n  params: {},\r\n});\r\n\r\nif (failure) throw failure;\r\n\r\nfor await (const chunk of iterator) {\r\n  const [chunkFailure, chunkData] = chunk;\r\n  if (chunkFailure) {\r\n    console.error(chunkFailure);\r\n    continue;\r\n  }\r\n  // 处理推送数据\r\n  handleStreamData(chunkData);\r\n}\r\n```\r\n\r\n## 典型场景：事件订阅\r\n\r\n在前端状态管理器工程中，`watch.stream.ts` 是核心的事件订阅端点，负责将后端的 `app:` 前缀事件实时推送到前端：\r\n\r\n```\r\n后端 action 中 context.emit('app:tabs', data)\r\n        ↓\r\nwatch.stream.ts 中 context._.on('*') 捕获，过滤 app: 前缀\r\n        ↓\r\nflow.emit() 推送到 SSE 流\r\n        ↓\r\n前端通过 stargate.execute('/event/watch~') 接收\r\n        ↓\r\naurora/defineAurora 解析并更新 ipcRefs\r\n        ↓\r\nVue 组件通过 useIpcRefs() 响应式读取\r\n```\r\n\r\n详细的前端使用方式请参阅 `./docs/point-store.md` 中的\"事件系统\"章节。\r\n\r\n## 最佳实践\r\n\r\n1. **过滤事件**：在 stream 中务必过滤事件，只推送客户端需要的数据（如 `app:` 前缀），避免推送不必要的服务端内部事件。\r\n2. **初始数据**：stream 建立连接后，应立即推送初始数据（如通过 `life-cycle:mounted` 事件），确保客户端首次连接时能获取到数据。\r\n3. **避免阻塞**：`flow.emit()` 是非阻塞的，不要在回调中执行耗时操作。\r\n4. **连接管理**：客户端断开连接时，生成器会自动结束，无需手动处理。\r\n",
    "SKILL.md": "---\r\nname: milkio\r\ndescription: 'cookbook，co 命令，milkio，后端，状态管理，Electron主进程，数据仓库，缓存，逻辑，测试；*.action.ts *.stream.ts __TEST__.test.ts *.config.ts *.table.ts *.cache.ts *.code.ts *.codes.ts *.event.ts *.handler.ts *.seed.ts *.types.ts *.data.ts *.utils.ts'\r\nmetadata:\r\n    xMilkioUpdatedAt: '2026-11-17T14:30:19.000Z'\r\n    xMilkioDoNotEdit: 'This document is managed and overwritten automatically by cookbook. Do not edit it; edit the canonical skill in the milkio repository instead.'\r\n---\r\n\r\n## 什么是 Milkio\r\n\r\nMilkio 是一个 AI native 的嵌入式逻辑层框架，它专注于处理和封装复杂的业务逻辑与状态，而不与 UI 视图耦合。\r\n\r\n你的 vue 组件需要通过调用 milkio 来获取数据状态、执行操作等，无论是否必须经过网络传输。因此，它可以有多种用途：\r\n\r\n- 作为后端服务器 (部署在云端，通过网络与前端通信)\r\n- 作为前端的状态管理器 (替代诸如 pinia、redux 等 store library)\r\n- 接管 Electron 的主进程并和渲染进程通信\r\n\r\n## 工程架构\r\n\r\n这是一个 monorepo，在 `./projects` 目录下存储着若干个工程。\r\n\r\n假设用户在制作一个 Todo 应用，支持网页在线使用和桌面应用程序。那么，用户通常会有以下目录：\r\n\r\n```\r\nprojects/\r\n├── todo-app/               # 前端应用 (nuxt app，内部包括路由和网页等，不包括任何逻辑和状态)\r\n├── todo-app-electron/      # 桌面应用程序 (milkio app，负责通过 electron 启动 BrowserWindow 并加载 todo-app)\r\n├── todo-app-embed/         # 前端状态管理器 (milkio app，以 shared worker / worker 的形式和 todo-app 运行在同一个浏览器内)\r\n└── todo-server/            # 后端服务器 (milkio app，运行在云端服务器中，通过网络与浏览器页面通信)\r\n```\r\n\r\n当用户启动了桌面应用程序后，实际产生的调用顺序如下：\r\n\r\n```\r\n`todo-app-electron`\r\n(启动桌面应用程序并通过启动 BrowserWindow 来打开前端应用的网页)\r\n====== ▼ ======\r\n`todo-app`\r\n(只负责界面呈现，具体逻辑与状态的处理，通过调用状态管理器完成)\r\n====== ▼ ======\r\n`todo-app-embed`\r\n(发送网络请求将数据传递到后端服务器)\r\n====== ▼ ======\r\n`todo-server`\r\n(处理数据并保存到数据库)\r\n```\r\n\r\n### 前端必须通过 embed 与后端通信\r\n\r\n**严禁**前端（`todo-app`）直接调用后端服务器（`todo-server`）的端点。无论是读取还是写入，前端都**必须**通过 embed（`todo-app-embed`）来与后端通信。\r\n\r\n```\r\n❌ 错误：前端直连后端\r\ntodo-app → stargate.execute('/space/browse') → todo-server\r\n\r\n✅ 正确：前端通过 embed 调用\r\ntodo-app → aurora.ipc.execute('/space/browse') → todo-app-embed → stargate.execute('/space/browse') → todo-server\r\n```\r\n\r\n理由：\r\n\r\n1. **架构一致性**：所有对 server 的调用都通过 embed 统一代理，embed 可以缓存读取结果、统一管理错误处理和重试逻辑，保持前端与 server 的解耦。\r\n2. **状态同步**：写操作后 embed 会自动 emit 事件通知前端；如果前端绕过 embed 直接调用 server，embed 无法感知数据变更，会导致状态不一致。\r\n3. **缓存控制**：embed 可以在写操作后自动刷新相关缓存，前端直连 server 则无法做到。\r\n4. **职责分离**：前端只负责 UI 呈现，embed 负责所有业务逻辑和数据通信，server 负责数据持久化。\r\n\r\n因此，前端代码中**不应出现**直接使用 `stargate.execute('/xxx/...')` 调用 server 端点的代码，而应统一使用 `aurora.ipc.execute('/xxx/...')` 调用 embed 端点。如果 embed 中尚未定义所需的端点，应先在 embed 中创建对应的 action，再由前端调用。\r\n\r\n---\r\n\r\n## 模式\r\n\r\n模式 (mode) ，它的作用是区分当前的开发环境。不同的模式会启用不同的配置文件，也会注入不同的环境变量。它也等同于设置 Vite 的模式，参见：[Env Variables and Modes](https://vite.dev/guide/env-and-mode)\r\n\r\n启动后，所有的工程都会收到 `MODE`、`VITE_MODE` 作为环境变量。我们推荐你使用 `VITE_MODE` 作为模式的依据，这样，能够兼容大部分 VITE 工程。在绝大多数情况下，例如，本地开发时，模式都最好固定是 `test`。因为，当模式为 `test` 时，我们会允许一些开发时可用的特性，例如启动开发服务器，允许 `co test` 正常工作。但是，这些特性会产生安全风险。因此，生产环境务必使用其他的模式，例如 `prod` 等。\r\n\r\n想要添加或修改模式，直接修改 `cookbook.toml` 中的 `general->modes` 字段即可。除了 `test` 模式是必须的，其他都是可以自由定义的。\r\n\r\n## 开发命令（`co` CLI）\r\n\r\n`co` 是 milkio 的开发工具链（cookbook），负责生成声明文件、启动/停止各工程、运行测试等。\r\n\r\n### `co generate`\r\n\r\n重新生成所有工程的声明文件，即 `.milkio/` 目录（typia 类型推导 + 路由类型）。\r\n\r\n如果你遇到端点不存在的 TS 类型错误，不用担心，这些类型错误在运行 `co generate` 时会自动消除。这是一个基础命令，当你运行其他如 `co start` 或者 `co test` 的命令时，它们会在内部先运行 `co generate`。\r\n\r\n```bash\r\nco generate --mode=test\r\n```\r\n\r\n### `co start`\r\n\r\n启动 `./projects` 目录下的所有工程。\r\n\r\n当你运行后，它会先启动所有的工程，包括前端工程（这等于运行 `npm run dev`）。并且，会自动按模式加载对应的模式配置。所以，不用担心多个服务之间是否启动的问题。\r\n\r\n```bash\r\nco start --mode=test\r\n```\r\n\r\n运行 `co start --mode=test` 后通常**不需要**运行 `co stop`：用户通常希望在你完成更改后直接预览结果，因此保持开发服务器在后台运行即可。除非用户显式要求你运行 `co stop`，否则不要主动停止它。\r\n\r\n### `co stop`\r\n\r\n停止所有由 `co start` 启动的工程进程。\r\n\r\n通常不需要主动执行：除非用户显式要求停止开发服务器，否则保持其后台运行（见上节说明）。\r\n\r\n```bash\r\nco stop\r\n```\r\n\r\n### `co test`\r\n\r\n运行测试，内部会使用 `vitest` 来运行测试。\r\n\r\n注意，你不能直接使用 `npx vitest` 来运行测试，由于所有的测试都会发生真实的 HTTP 请求，而使用 `vitest` 或 `jest` 会因为服务器未启动而失败。因此，你需要使用 `co test` 来运行测试，当你运行后，它会先启动所有的工程，然后再运行测试。所以不用担心多个服务之间是否启动的问题。\r\n\r\n```bash\r\n# 运行单个测试文件\r\nco test \"./projects/todo-app-embed/app/modules/setting/__TEST__.test.ts\" --mode=test\r\n\r\n# 运行多个指定测试文件\r\nco test \"./projects/todo-app-embed/app/modules/setting/__TEST__.test.ts\" \"./projects/todo-app-embed/app/modules/other/__TEST__.test.ts\" --mode=test\r\n\r\n# 运行全部的测试 (对于大型仓库可能需要运行几十分钟)\r\nco test --mode=test\r\n```\r\n\r\n### `co logs`\r\n\r\n查看统一日志收集器收集到的日志。`co start` / `co dev` / `co test` 启动的所有进程（后台 dev 进程、各 project 的开发服务器、测试子进程、类型检查/构建子进程等）的输出都会带时间戳、来源和 stdout/stderr 标记写入同一个日志存储，进程崩溃、被强杀、健康检查失败等事件的错误信息也会被记录下来。\r\n\r\n日志按「一次运行（session）」分组：\r\n\r\n- 每次 `co start` / `co dev` / `co test` 都会创建一个新的 session，**不会清空历史日志**。\r\n- 直接运行 `co logs` 时：如果有正在运行的 session，则查看**本次运行**；否则查看**上一次运行**的最末尾。\r\n- 查看更早的运行需要显式使用 `--sessions` / `--session`。\r\n\r\n```bash\r\n# 查看本次运行的日志（新的在最上面；默认一页，约 64KB）\r\nco logs\r\n\r\n# 列出保留的所有运行（编号、开始时间、模式、状态、磁盘占用）\r\nco logs --sessions\r\n\r\n# 查看历史运行：--session 1 = 最新/本次，2 = 上一次，也接受 session id 前缀\r\nco logs --session 2\r\nco logs --session 2 -e\r\n# 合并所有保留的运行\r\nco logs --session all\r\n```\r\n\r\n默认输出为**倒序（越新越靠上）**，每行都带本地时间（精确到毫秒）、来源和 stream。一页显示不下时，日志结尾会有醒目的英文提示，并给出可直接复制执行的翻页命令：\r\n\r\n```text\r\n════════════════════════════════════════════════════════════════════════════\r\n  MORE LOGS AVAILABLE — OLDER ENTRIES CONTINUE ON PAGE 2  (newest first)\r\n\r\n  To view older logs, run:\r\n      co logs --cursor=c1.eyJ2IjoxLC...\r\n\r\n  To return to the newest logs, run:\r\n      co logs\r\n════════════════════════════════════════════════════════════════════════════\r\n```\r\n\r\n翻页采用**游标（cursor）**而不是页码：`--cursor` 是当前位置的书签，新日志不断写入也不会让旧页内容漂移或重复。翻页命令已经携带了当时的 session、过滤条件和每页大小，所以只需复制整条命令即可；`--cursor` 不能和 `--session`、`-e`、`-s`、`--from`、`--to`、`--project`、`--ready`、`--page-size` 一起使用。\r\n\r\n```bash\r\n# 只看错误（stderr、含英文单词 error/fail（不区分大小写，含 errors/failed/failure 等词形），\r\n# 或含中文 错误/异常 的行）\r\nco logs -e\r\nco logs --errors\r\n\r\n# 查看各进程是何时就绪的（健康检查通过的时间、耗时、探测次数、URL）\r\nco logs --ready\r\n# 只看某个项目的就绪情况（匹配 worker:<name> 或事件里的 project 字段）\r\nco logs --ready --project todo-server\r\n\r\n# 关键词搜索（大小写不敏感；可重复，多个条件同时满足）\r\nco logs -s timeout\r\nco logs -e -s ECONNREFUSED -s \"数据库\"\r\n\r\n# 按时间范围筛选（精确到秒，含边界；不带时区时按本机时区解析）\r\n# 支持 YYYY-MM-DD、YYYY-MM-DD HH:mm、YYYY-MM-DD HH:mm:ss 和 ISO 8601\r\nco logs --from \"2026-10-21 00:05:00\" --to \"2026-10-21 00:10:00\"\r\nco logs -e --from \"2026-10-21\" --to \"2026-10-21 23:59:59\"\r\n\r\n# 统计当前筛选条件下总共有多少条匹配日志（会完整扫描一遍，内存占用仍是常数级）\r\nco logs -e --count\r\n\r\n# 调整每页数据量（默认 64kb；页面按完整行累计，不会把一行拆到两页）\r\nco logs --page-size 32kb\r\nco logs --page-size 128kb\r\n\r\n# 实时跟踪当前运行的新日志（仅 TTY；仅在 session 正在运行时可用；忽略分页）\r\nco logs -f\r\nco logs -f -e\r\n\r\n# 关闭颜色（输出到管道时也会自动关闭）\r\nco logs --no-color\r\n```\r\n\r\n补充说明：\r\n\r\n- 日志位置：`<工作目录>/node_modules/.cookbook/logs/sessions/<sessionId>/`。\r\n- 逐出机制避免无限膨胀：默认最多 256MB、20 个 session、当前 session 最多 128MB；可用环境变量 `COOKBOOK_LOG_MAX_BYTES`、`COOKBOOK_LOG_MAX_SESSIONS`、`COOKBOOK_LOG_MAX_SESSION_BYTES` 覆盖。超过上限时优先删除最旧的、已经结束的 session；当前正在运行的 session 永不删除。\r\n- `--ready` 依赖后台 dev 进程统一执行健康检查（轮询间隔 500ms、单次请求超时 5s、总超时默认 600s，可用 `COOKBOOK_READY_TIMEOUT_MS` 覆盖）。失败/超时同时会作为错误事件出现在 `co logs -e` 中。\r\n- 单行日志上限 1MB（极端超长行会被截断并标记），正常日志不会被截断；分页只在完整行之间断开。\r\n- 进程被强制结束（例如 Windows 上 `taskkill /F`）时，最多丢失最后约 50ms 的缓冲；`co stop` 自身会向对应 session 写入停止事件，便于事后追溯。\r\n- `co logs` 自身不会创建 session，也不会写入日志文件。\r\n\r\n### 技能自动更新\r\n\r\n本技能由 `co` 自带。当 milkio 版本变化（`.milkio/.version` 与当前 `co` 版本不一致）并重新生成 `.milkio/` 声明文件时（例如运行 `co generate`、`co start`、`co test`），`co` 会检索当前仓库内各 AI 工具的技能目录（`.agents/skills/milkio`、`.claude/skills/milkio`、`.codebuddy/skills/milkio`、`.trae/skills/milkio`、`.workbuddy/skills/milkio`、`.dsh/skills/milkio` 等），把其中已有的 `milkio` 技能目录整体替换为当前版本，保证多份技能副本与 `co` 版本一致。不会创建原本不存在的技能目录，也不会触碰全局（用户目录下的）技能目录。\r\n\r\n因此，如果你发现某个技能副本内容不一致，优先检查 `co` 版本是否已升级；升级后运行一次 `co generate --mode=<模式>` 即可让所有副本对齐。\r\n\r\n---\r\n\r\n## 文档\r\n\r\n你必须阅读文档，了解实际的开发流程和规范。\r\n\r\n你必须严格依据相关文档进行开发。编码完成后必须复查代码，确保完全符合文档要求。此外，若在编码结束后发现涉及的改动与某些尚未阅读的文档有关，务必阅读这些文档然后重新编码。切勿凭直觉编码，否则极有可能严重偏离规范与目标。\r\n\r\n### 模块\r\n\r\n模块是位于 `/app/modules` 目录下的文件夹，采用**小写字母+中划线**命名，并且必须使用**单数名词**（不以字母 s 结尾）。例如：用户模块为 `/app/modules/user`，用户设备模块为 `/app/modules/user-device`。创建文件夹即会自动注册为模块。\r\n\r\n模块下可以嵌套子模块（例如，商品 `product` 为主模块，商品规格 `specification` 为其子模块，路径就是 `/app/modules/product/specification`）。父模块和子模块的资源可以互相调用，例如子模块操作父模块的 database 或 store，但是，不能跨模块互相调用。遇到需要跨模块调用的情形，必须通过 API 端点或者 events 的方式实现，可参阅相关文档。\r\n\r\n- `./docs/events.md`：当你需要跨模块通信时阅读。\r\n\r\n### 通信\r\n\r\nStargate 是 milkio 的客户端通信 SDK，你必须使用它进行通信。\r\n\r\n**前端 vue 工程不得直接使用 stargate 与 server 通信，必须通过 `aurora.ipc.execute` 调用 embed 端点。** stargate 仅在 embed 和 server 等 Milkio 工程内部使用。\r\n\r\n每一个 milkio app 都可以被外部的其他工程调用，通过类似以下方式发送\"请求\"至某一个 API 端点。注意，这里的\"请求\"并非一定会产生实际的网络请求，也可能实际上只是在 javascript 进程内互相调用函数。但是，它们都被封装为了一个统一的接口，你无需关心实际的通信方式。\r\n\r\n```ts\r\n// ❌ 错误：前端 vue 工程中直接使用 stargate 调用 server\r\nconst [error, result, details] = await stargate.execute('/user/login', {\r\n  params: { hello: 'Milkio' },\r\n});\r\n\r\n// ✅ 正确：前端 vue 工程中通过 embed 调用\r\nconst aurora = await useAurora();\r\nconst [error, result, details] = await aurora.ipc.execute('/user/login', {\r\n  params: { hello: 'Milkio' },\r\n});\r\n```\r\n\r\n在 embed 等 Milkio 工程内部，使用 stargate 与其他 Milkio 工程通信：\r\n\r\n```ts\r\n// embed 工程中，使用 stargate 调用 server\r\nconst [error, result, details] = await stargate.execute('/user/login', {\r\n  params: {\r\n    hello: 'Milkio',\r\n  },\r\n});\r\n\r\nif (error) {\r\n  // 处理错误..\r\n}\r\n\r\nconsole.log(result);\r\n```\r\n\r\n- `./docs/stargate.md`：当你要需要进行通信时阅读。\r\n- `./docs/create-stargate.md`：当你需要创建一个与其他子工程通信用的 stargate 时阅读。\r\n\r\n### API 端点与测试 (`*.action.ts / *.stream.ts / __TEST__.test.ts`)\r\n\r\n每一个 milkio app 的 `./app/modules` 目录下，都包含了若干个 `.action.ts` 文件，每个 action 文件都对应一个 API 接口，它所在的位置，会自动映射成约定式路由。例如，`./app/modules/user/login.action.ts` 会被路由为 `/user/login`、`./app/modules/foo/index.action.ts` 会被路由为 `/foo`。\r\n\r\n每个模块都必须在目录下创建一个 `__TEST__.test.ts` 文件，里面编写该模块所有端点的测试代码。当你修改了任何代码，都必须运行 `co test` 进行测试验证。\r\n\r\n- `./docs/point.md`：当你要修改或者编写 API 端点时阅读，或者修改对应端点的测试文件 `__TEST__.test.ts` 时阅读。此外，你还需要额外阅读以下任意一篇文档，**你不能只阅读本文档**：\r\n  - `./docs/point-server.md`：如果是用作后端服务器的工程时阅读。\r\n  - `./docs/point-store.md`：如果是用作前端状态管理器的工程时阅读。\r\n\r\n### 配置 (`*.config.ts`)\r\n\r\n在开发过程中，通常需要妥善管理各种配置信息，例如数据库连接详情、密钥等敏感数据。这些配置往往与运行模式强相关，因此需要一种可维护、可扩展、类型安全的管理方式。Milkio 为此提供了一套基于模式的配置系统。\r\n\r\n当你需要修改包括 common.config.ts、test.config.ts、dvlp-zh-cn.config.ts、prod-zh-cn.config.ts 等基于模式的配置文件时一定要阅读文档。\r\n\r\n你可以通过 `context.config` 来访问配置。\r\n\r\n- `./docs/config.md`：当你需要编写配置时阅读。\r\n\r\n### 数据库（`*.table.ts`）\r\n\r\n对于用作后端服务器的工程，通常需要操作数据库。使用 drizzle 操作数据库是首选的方式。\r\n\r\n- `./docs/drizzle.md`：当你要需要编写数据库相关代码时阅读。\r\n\r\n迁移命令由 **AI 自己运行**（如 `co drizzle generate --project=<项目名> --mode=<模式名> --yes --json`），无需用户执行；详见该文档的「数据库迁移」章节。\r\n\r\n### 缓存（`*.cache.ts`）\r\n\r\nMilkio 内置缓存功能（进程内缓存），可以避免热点数据对数据库造成太大的压力，或者实现布隆过滤器。\r\n\r\n它不是分布式缓存，因此不适合实现分布式锁。需要幂等或锁的场景，应当依赖数据库自身的原子性（唯一索引、条件更新、事务）来保证。\r\n\r\n- `./docs/cache.md`：当你要编写缓存相关代码时阅读。\r\n\r\n### 内部动作（`$exports`）\r\n\r\n有些动作不需要对外暴露为 HTTP 接口，仅供模块内部或其他模块通过 `context.call()` 调用。这类动作放在模块的 `$exports` 目录下。**`$exports` 目录中的动作不会注册为端点。**\r\n\r\n```ts\r\n// 在 action 中调用 $exports\r\nconst result = await context.call(import('../point/$exports/add.action.ts'), {\r\n  data: { userId: params.data.userId, points: 100 },\r\n});\r\n```\r\n\r\n- `./docs/point-server.md`：内部动作的详细写法和 `context.call` 的用法在本文档的\"$exports\"章节中。\r\n\r\n### 错误码（`*.code.ts`）\r\n\r\n错误码分为两类，**定义在同一个 `*.code.ts` 里**，每个文件必须同时导出 `Fail` 与 `Fault`（可以为空）：\r\n\r\n- `Fail`：业务侧预期内的拒绝（warn 级、无堆栈、data 返回客户端）；\r\n- `Fault`：意料外/内部错误（error 级、带堆栈、对客户端完全隐藏，仅本工程内部使用）。\r\n\r\n**公共错误码**定义在 `/app/codes/` 目录下（如 `common.code.ts`），所有模块共享。**模块专属错误码**定义在模块的 `$codes` 目录下。\r\n\r\n```ts\r\n// 使用错误码\r\nthrow context.fail('DATA_NOT_FOUND', undefined); // 公共错误码\r\nthrow context.fail('POINT_INSUFFICIENT', { required: 100, available: 50 }); // 模块错误码\r\nthrow context.fault('POINT_LEDGER_INVARIANT_BROKEN', { ledgerId }); // 内部 fault-code\r\n```\r\n\r\n- `./docs/point-server.md`：错误码的定义、fail/fault 判定和使用规范在本文档的\"错误处理\"章节中。\r\n\r\n### 启动引导、中间件（`bootstrap`）\r\n\r\nBootstrap 用于在服务启动时初始化中间件、数据库连接等基础设施。\r\n\r\n- `./docs/bootstrap.md`：当你需要编写启动引导逻辑时阅读。\r\n\r\n### 实时推送（`*.stream.ts`）\r\n\r\nStream 端点基于 Server-Sent Events (SSE) 实现服务端向客户端的实时推送，使用 `async function*` 异步生成器定义。路由路径末尾加 `~` 后缀。\r\n\r\n- `./docs/stream.md`：当你需要编写实时推送功能时阅读。\r\n\r\n### 事件与事件监听（`*.event.ts + *.handler.ts`）\r\n\r\n事件是模块间通信的核心机制。模块通过 `$events` 目录定义事件（`*.event.ts`），通过 `$handlers` 目录监听事件（`*.handler.ts`），实现解耦协作。\r\n\r\n- `./docs/events.md`：当你需要定义事件、编写事件监听、或进行跨模块通信时阅读。\r\n\r\n### 类型、数据与工具方法（`$types` / `$data` / `$utils`）\r\n\r\n模块目录下**禁止**直接散放共享 `.ts` 文件（如 `xxx-shared.ts`、`xxx-service.ts`）。模块内需要复用的代码，按性质归入以下三个目录：\r\n\r\n- **类型 → `$types`**（`*.types.ts`）：跨文件复用的 type / interface 定义。\r\n- **数据 → `$data`**（`*.data.ts`）：常量表、模块级运行时缓存（如 `Map` 缓存）等静态或长生命周期数据。\r\n- **工具方法 → `$utils`**（`*.utils.ts`）：纯函数工具。**抽离前必须确认调用处至少为两处**（测试文件不计入）；只有一处调用时，直接以过程式的写法，内联在调用处所在文件的逻辑中，不要抽离成公共方法。\r\n\r\n### 模块目录总览\r\n\r\n```\r\napp/modules/{module-name}/\r\n├── $databases/        # 数据库表定义（*.table.ts）\r\n├── $caches/           # 二级缓存（*.cache.ts）\r\n├── $events/           # 事件定义（*.event.ts）\r\n├── $handlers/         # 事件监听（*.handler.ts）\r\n├── $exports/          # 内部动作（*.action.ts，不注册为端点）\r\n├── $codes/            # 模块专属错误码（*.code.ts）\r\n├── $seeds/            # 测试种子数据（*.seed.ts）\r\n├── $configs/          # 模块配置（*.config.ts）\r\n├── $types/            # 类型定义（*.types.ts）\r\n├── $data/             # 常量表、模块级缓存等数据（*.data.ts）\r\n├── $utils/            # 工具方法（*.utils.ts，调用处 ≥2 才允许抽离）\r\n├── $stores/           # 前端存储（仅状态管理器工程）\r\n├── $bootstraps/       # 模块级启动引导\r\n├── add.action.ts      # API 端点\r\n├── browse.action.ts\r\n├── read.action.ts\r\n├── edit.action.ts\r\n├── delete.action.ts\r\n└── __TEST__.test.ts      # 测试文件\r\n```\r\n"
};
